head.b:skin:
/* 주유소찾기 - 블로그스팟 전용 테마 (scripts/build_theme.py 로 자동 생성) */
/* 주유소찾기 - 테마 껍데기 (헤더·탭·푸터·블로그 글) */

:root {
  --oil-bg: #EFF1F0;
  --oil-card: #FFFFFF;
  --oil-line: #DDE3E1;
  --oil-line-soft: #E9EEEC;
  --oil-soft: #F5F7F6;
  --oil-ink: #13181A;
  --oil-ink2: #4A5558;
  --oil-muted: #5B666A;
  --oil-muted2: #8A9599;
  --oil-accent: #D96206;
  --oil-accent-dark: #A54A04;
  --oil-accent-soft: #FDF0E4;
  --oil-teal: #0B6B60;
  --oil-teal-dark: #0A5850;
  --oil-teal-soft: #E2F1EE;
  --oil-max: 768px;
}

html, body {
  margin: 0; padding: 0;
  background: var(--oil-bg);
  color: var(--oil-ink);
  font-family: Pretendard, "IBM Plex Sans KR", system-ui, -apple-system, sans-serif;
  word-break: keep-all;
  overflow-wrap: break-word;
  -webkit-text-size-adjust: 100%;
}
* { box-sizing: border-box; }
a { color: var(--oil-accent-dark); text-decoration: none; }
button, input, select { font-family: inherit; }

/* 헤더 - 가운데 정렬 2줄 (제목 / 안내문구) */
.oil-header {
  background: var(--oil-card);
  border-bottom: 1px solid var(--oil-line);
  padding: 10px 16px 9px;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  text-align: center;
  position: sticky; top: 0; z-index: 30;
}
.oil-logo {
  font-size: 18px; font-weight: 900; letter-spacing: -0.03em; color: var(--oil-ink);
}
.oil-sub { font-size: 11.5px; color: #ef4444; font-weight: 600; line-height: 1.5; }
.oil-sub b { font-weight: 700; }
.oil-sub-sep { color: var(--oil-line); font-style: normal; margin: 0 3px; }

/* 탭도 가운데로 맞춘다 */
.oil-tabs ul { justify-content: center; }

/* 탭 */
.oil-tabs {
  background: var(--oil-card);
  border-bottom: 1px solid var(--oil-line);
  overflow-x: auto; -webkit-overflow-scrolling: touch;
}
.oil-tabs ul {
  display: flex; gap: 2px; margin: 0 auto; padding: 0 12px;
  max-width: var(--oil-max); list-style: none;
}
.oil-tabs a {
  display: block; flex-shrink: 0; white-space: nowrap;
  padding: 11px 10px 9px; font-size: 12.5px; font-weight: 500;
  color: #6B7679; border-bottom: 2px solid transparent;
}
.oil-tabs a.active { color: var(--oil-ink); font-weight: 700; border-bottom-color: var(--oil-ink); }

/* 본문 자리 */
#oil-root { max-width: var(--oil-max); margin: 0 auto; padding: 16px; }
#oil-root:empty { min-height: 60vh; }

/* 푸터 */
.oil-footer {
  max-width: var(--oil-max); margin: 24px auto 0; padding: 16px 16px 28px;
  font-size: 11.5px; line-height: 1.65; color: var(--oil-muted);
  border-top: 1px solid var(--oil-line);
}
.oil-footer b { color: var(--oil-ink); margin-right: 6px; }

/* 일반 블로그 글 (앱 화면에서는 숨김) */
.oil-blog-wrap { max-width: var(--oil-max); margin: 0 auto; padding: 16px; }
.oil-mode-find .oil-blog-wrap,
.oil-mode-near .oil-blog-wrap,
.oil-mode-browse .oil-blog-wrap,
.oil-mode-area .oil-blog-wrap,
.oil-mode-calc .oil-blog-wrap { display: none; }
.oil-blog-wrap .post {
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 16px; padding: 22px; margin: 0 0 16px;
}
.oil-blog-wrap .post-title { font-size: 21px; font-weight: 800; margin: 0 0 14px; letter-spacing: -0.02em; }
.oil-blog-wrap .post-title a { color: var(--oil-ink); }
.oil-blog-wrap .post-body { font-size: 16px; line-height: 1.8; color: var(--oil-ink2); }
.oil-blog-wrap .post-body img { max-width: 100%; height: auto; border-radius: 10px; }
.oil-blog-wrap .post-body h2 { font-size: 19px; margin: 26px 0 10px; color: var(--oil-ink); }
.oil-blog-wrap .post-body h3 { font-size: 17px; margin: 22px 0 8px; color: var(--oil-ink); }

/* 주유소찾기 - 화면 스타일 */

/* 공통 조각 */
.oil-stack { display: flex; flex-direction: column; gap: 12px; }
.oil-card {
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 16px; padding: 16px;
}
.oil-card.is-accent { border-color: var(--oil-accent); box-shadow: 0 0 0 3px var(--oil-accent-soft); }
.oil-card.is-teal { border-color: var(--oil-teal); box-shadow: 0 0 0 3px var(--oil-teal-soft); }
.oil-card.is-flush { padding: 16px 0 6px; }
.oil-card-title {
  font-size: 17px; font-weight: 900; letter-spacing: -0.02em; color: var(--oil-ink);
  margin: 0 0 10px;
}
.oil-kicker {
  font-size: 11px; font-weight: 700; letter-spacing: 0.1em; color: var(--oil-accent-dark);
}
.oil-h1 {
  margin: 5px 0 0; font-size: 23px; font-weight: 900; letter-spacing: -0.03em;
  color: var(--oil-ink); line-height: 1.32;
}
.oil-lead { margin: 10px 0 0; font-size: 13.5px; line-height: 1.7; color: var(--oil-ink2); }
.oil-p { margin: 0 0 11px; font-size: 13.5px; line-height: 1.75; color: var(--oil-ink2); }
.oil-p:last-child { margin-bottom: 0; }
.oil-p b, .oil-lead b { font-weight: 700; color: var(--oil-ink); }
.oil-hero {
  font-size: 34px; font-weight: 900; letter-spacing: -0.03em;
  color: var(--oil-accent-dark); line-height: 1.1;
}
.oil-hero-unit { font-size: 13px; color: var(--oil-muted); font-weight: 500; margin-left: 7px; }

/* 표 */
.oil-rows { border: 1px solid var(--oil-line-soft); border-radius: 11px; overflow: hidden; margin-top: 13px; }
.oil-row {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  padding: 10px 12px; font-size: 12.5px; border-bottom: 1px solid var(--oil-line-soft);
}
.oil-row:last-child { border-bottom: 0; background: var(--oil-soft); }
.oil-row-k { color: var(--oil-muted); }
.oil-row-v { font-weight: 700; color: var(--oil-ink); text-align: right; }
.oil-row-v.is-accent { color: var(--oil-accent-dark); }

/* 주유소 목록 */
.oil-list-item {
  display: flex; justify-content: space-between; align-items: center; gap: 8px;
  padding: 11px 16px;
}
.oil-list-item:nth-child(even) { background: var(--oil-soft); }
.oil-list-name { font-size: 12.5px; color: var(--oil-ink); min-width: 0; }
.oil-list-price { font-size: 13.5px; font-weight: 700; color: var(--oil-ink); flex-shrink: 0; }
.oil-tag { font-size: 10.5px; color: #6B7679; margin-left: 4px; }
.oil-badge {
  font-size: 10.5px; font-weight: 600; padding: 2px 6px; border-radius: 5px; margin-left: 5px;
  white-space: nowrap;
}
.oil-badge.is-low { background: #E4F2E8; color: #0F5628; }
.oil-badge.is-high { background: #FBEAE4; color: var(--oil-accent-dark); }

/* 지역 선택 */
.oil-sido-tabs { display: flex; flex-wrap: wrap; gap: 6px; }
.oil-chip {
  font-size: 12px; padding: 7px 11px; border-radius: 9px;
  border: 1px solid var(--oil-line); background: var(--oil-card); color: var(--oil-ink2);
  cursor: pointer;
}
.oil-chip.active { background: var(--oil-ink); color: #fff; border-color: var(--oil-ink); font-weight: 600; }
.oil-region-grid { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 11px; }
.oil-region-grid a {
  font-size: 11.5px; padding: 5px 10px; border-radius: 7px;
  border: 1px solid var(--oil-line); color: var(--oil-ink2); background: var(--oil-card);
}
.oil-search {
  width: 100%; padding: 12px 13px; font-size: 15px; font-weight: 500;
  border: 1px solid var(--oil-line); border-radius: 11px; background: var(--oil-card);
  color: var(--oil-ink);
}
.oil-suggest { margin-top: 8px; display: flex; flex-direction: column; }
.oil-suggest a {
  padding: 10px 12px; font-size: 13px; color: var(--oil-ink);
  border-bottom: 1px solid var(--oil-line-soft);
}
.oil-suggest a:last-child { border-bottom: 0; }
.oil-suggest .s { color: var(--oil-muted); font-size: 11.5px; margin-left: 6px; }

/* 순위 목록 */
.oil-rank a {
  display: flex; justify-content: space-between; align-items: center;
  padding: 10px 16px; font-size: 12.5px; color: var(--oil-ink);
}
.oil-rank a:nth-child(even) { background: var(--oil-soft); }
.oil-rank .v { font-weight: 700; color: var(--oil-accent-dark); flex-shrink: 0; }

/* 버튼 */
.oil-btn {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  padding: 14px; border-radius: 14px; background: var(--oil-ink); color: #fff;
  font-size: 13px; font-weight: 700;
}
.oil-btn.is-ghost {
  background: var(--oil-card); color: var(--oil-ink2); border: 1px solid var(--oil-line);
  font-weight: 500; font-size: 12.5px; padding: 12px 14px;
}
.oil-btn svg { flex-shrink: 0; }

/* 계산기 */
.oil-field { margin-bottom: 13px; }
.oil-field label { display: block; font-size: 12.5px; font-weight: 600; color: var(--oil-ink2); margin-bottom: 6px; }
.oil-field-in { display: flex; align-items: center; gap: 8px; }
.oil-field input, .oil-field select {
  flex-grow: 1; min-width: 0; padding: 11px 12px; font-size: 15px; font-weight: 600;
  color: var(--oil-ink); background: var(--oil-card);
  border: 1px solid var(--oil-line); border-radius: 11px;
}
.oil-field-unit { flex-shrink: 0; font-size: 12.5px; color: var(--oil-muted); }
.oil-field-hint { font-size: 11px; color: var(--oil-muted2); margin-top: 4px; }

/* 내 설정 (유종·차종) */
.oil-prefs {
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 14px; overflow: hidden;
}
.oil-prefs-sum {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  width: 100%; padding: 12px 14px; background: none; border: 0; cursor: pointer;
  text-align: left;
}
.oil-prefs-sum-t { font-size: 12.5px; font-weight: 600; color: var(--oil-ink); }
.oil-prefs-sum-a { font-size: 12px; font-weight: 600; color: var(--oil-accent-dark); flex-shrink: 0; }
.oil-prefs-body { display: none; padding: 0 14px 14px; }
.oil-prefs.is-open .oil-prefs-body { display: block; }
.oil-prefs.is-open .oil-prefs-sum-a::after { content: ' 닫기'; }
.oil-prefs-row {
  display: flex; align-items: flex-start; gap: 10px; padding-top: 10px;
  border-top: 1px solid var(--oil-line-soft);
}
.oil-prefs-row + .oil-prefs-row { margin-top: 10px; }
.oil-prefs-k {
  flex-shrink: 0; width: 34px; font-size: 12px; font-weight: 600;
  color: var(--oil-muted); padding-top: 7px;
}
.oil-prefs-hint { font-size: 11.5px; color: var(--oil-muted2); margin-top: 10px; line-height: 1.6; }

/* 찾은 현위치 표시 */
.oil-spot {
  display: inline-block; margin-top: 8px; padding: 5px 10px; border-radius: 8px;
  background: var(--oil-soft); border: 1px solid var(--oil-line-soft);
  font-size: 12px; color: var(--oil-muted);
}

/* 내 위치 버튼 */
.oil-locate {
  display: flex; align-items: center; justify-content: center; gap: 7px;
  width: 100%; padding: 13px; border-radius: 13px; cursor: pointer;
  background: var(--oil-ink); color: #fff; border: 0;
  font-size: 13.5px; font-weight: 700;
}
.oil-locate[disabled] { opacity: .6; }
.oil-locate-msg { font-size: 12px; color: var(--oil-muted); margin-top: 8px; line-height: 1.6; }
.oil-locate-msg:empty { display: none; }

/* 저장된 우리 동네 */
.oil-mine {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  background: var(--oil-card); border: 1px solid var(--oil-accent);
  box-shadow: 0 0 0 3px var(--oil-accent-soft);
  border-radius: 16px; padding: 15px 16px;
}
.oil-mine-k { font-size: 11px; font-weight: 700; letter-spacing: .08em; color: var(--oil-accent-dark); }
.oil-mine-r { font-size: 17px; font-weight: 900; color: var(--oil-ink); margin-top: 3px; letter-spacing: -.02em; }
.oil-mine-s { font-size: 12px; color: var(--oil-muted); margin-top: 3px; }

/* 집·회사 저장 */
.oil-save-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.oil-save {
  padding: 12px 0; border-radius: 12px; cursor: pointer; text-align: center;
  background: var(--oil-card); border: 1px solid var(--oil-line);
  font-size: 12.5px; font-weight: 600; color: var(--oil-ink2);
}
.oil-save.is-on { background: var(--oil-ink); color: #fff; border-color: var(--oil-ink); }

/* 광고 */
.oil-ad { margin: 2px 0; }
.oil-ad-label {
  font-size: 10px; font-weight: 600; letter-spacing: 0.08em;
  color: var(--oil-muted2); margin-bottom: 6px;
}
/* 개발 중 빈 광고 자리 - 나중에 광고를 켜도 화면이 밀리지 않게 자리를 잡아둔다 */
.oil-ad.is-empty {
  display: flex; align-items: center; justify-content: center;
  min-height: 250px; border: 1px dashed var(--oil-line);
  border-radius: 14px; background: var(--oil-soft);
}
.oil-ad.is-empty span {
  font-size: 11.5px; letter-spacing: 0.1em; color: var(--oil-muted2);
}

/* ── 첫 화면 (장소 검색 / 내 주변) ─────────────────────────── */
.oil-find { display: flex; flex-direction: column; gap: 22px; }
.oil-find-h {
  margin: 0 0 9px; font-size: 14px; font-weight: 800;
  letter-spacing: -0.02em; color: var(--oil-ink);
}
.oil-find-hint { margin: 8px 2px 0; font-size: 11.5px; color: var(--oil-muted2); }

/* 진짜 입력칸이 아니라 검색 화면을 여는 버튼이다 */
.oil-fakein {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  width: 100%; padding: 15px 15px; cursor: pointer; text-align: left;
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 13px; font-size: 14.5px; color: var(--oil-muted2);
}
.oil-fakein svg { color: var(--oil-ink); flex-shrink: 0; }

.oil-near-btn {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  width: 100%; padding: 16px 15px; cursor: pointer; text-align: left;
  background: var(--oil-teal); color: #fff; border: 0; border-radius: 13px;
}
.oil-near-btn[disabled] { opacity: .65; }
.oil-near-l { display: flex; align-items: center; gap: 11px; min-width: 0; }
.oil-near-l > span { min-width: 0; }
.oil-near-l .oil-pin { flex-shrink: 0; opacity: .9; }
.oil-near-t { display: block; font-size: 15px; font-weight: 800; letter-spacing: -0.02em; }
.oil-near-price { display: block; font-size: 13px; margin-top: 4px; opacity: .95; }
.oil-near-price b { font-weight: 500; opacity: .75; margin-right: 4px; }
.oil-near-price b + * { margin-left: 0; }
.oil-near-price b:not(:first-child) { margin-left: 10px; }
.oil-near-where { display: block; font-size: 11.5px; margin-top: 4px; opacity: .8; line-height: 1.5; }

/* ── 장소 검색 화면 (덮는 화면) ────────────────────────────── */
body.oil-noscroll { overflow: hidden; }
.oil-sheet {
  position: fixed; inset: 0; z-index: 90; background: var(--oil-bg);
  display: none; flex-direction: column;
}
.oil-sheet.is-open { display: flex; }
.oil-sheet-bar {
  display: flex; align-items: center; gap: 4px; flex-shrink: 0;
  padding: 8px 8px; background: var(--oil-card);
  border-bottom: 1px solid var(--oil-line);
}
.oil-sheet-ico {
  flex-shrink: 0; width: 38px; height: 38px; display: flex;
  align-items: center; justify-content: center; cursor: pointer;
  background: none; border: 0; color: var(--oil-ink2); border-radius: 9px;
}
.oil-sheet-in {
  flex-grow: 1; min-width: 0; padding: 10px 4px; font-size: 15.5px;
  border: 0; outline: none; background: none; color: var(--oil-ink);
}
.oil-sheet-in::-webkit-search-cancel-button { display: none; }
.oil-sheet-body { flex-grow: 1; overflow-y: auto; -webkit-overflow-scrolling: touch; padding-bottom: 30px; }

.oil-sheet-note {
  padding: 11px 16px; font-size: 12.5px; font-weight: 600;
  background: var(--oil-accent-soft); color: var(--oil-accent-dark);
}
.oil-sheet-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 15px 16px 8px; font-size: 12.5px; font-weight: 700; color: var(--oil-ink);
}
.oil-sheet-clearall {
  background: none; border: 0; cursor: pointer; padding: 0;
  font-size: 11.5px; font-weight: 500; color: var(--oil-accent-dark);
}
.oil-sheet-empty {
  padding: 34px 16px; text-align: center; font-size: 13px; color: var(--oil-muted);
  line-height: 1.7;
}
.oil-sheet-empty span { font-size: 11.5px; color: var(--oil-muted2); }

/* 집 / 회사 */
.oil-slots { display: flex; flex-wrap: wrap; gap: 7px; padding: 14px 16px 2px; }
.oil-slot {
  display: inline-flex; align-items: center; border-radius: 10px;
  border: 1px solid var(--oil-line); background: var(--oil-card); overflow: hidden;
}
.oil-slot.is-empty {
  padding: 9px 13px; cursor: pointer; font-size: 12.5px; color: var(--oil-muted2);
}
.oil-slot-go {
  background: none; border: 0; cursor: pointer; padding: 9px 4px 9px 13px;
  font-size: 12.5px; font-weight: 600; color: var(--oil-ink);
  max-width: 190px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.oil-slot-x {
  background: none; border: 0; cursor: pointer; padding: 9px 11px 9px 7px;
  font-size: 11px; color: var(--oil-muted2);
}

/* 검색 결과 · 최근 검색 목록 */
.oil-hits { background: var(--oil-card); border-top: 1px solid var(--oil-line-soft); }
.oil-hit {
  display: flex; align-items: center;
  border-bottom: 1px solid var(--oil-line-soft);
}
.oil-hit-go {
  display: flex; align-items: flex-start; gap: 10px; min-width: 0;
  flex-grow: 1; padding: 13px 8px 13px 16px; cursor: pointer;
  background: none; border: 0; text-align: left;
}
.oil-hit-go .oil-pin { flex-shrink: 0; margin-top: 2px; color: var(--oil-muted2); }
.oil-hit-go > span { min-width: 0; }
.oil-hit-go b {
  display: block; font-size: 14px; font-weight: 600; color: var(--oil-ink); line-height: 1.4;
}
.oil-hit-go i {
  display: block; font-style: normal; font-size: 11.5px; color: var(--oil-muted2);
  margin-top: 2px; line-height: 1.4;
}
.oil-hit-x {
  flex-shrink: 0; background: none; border: 0; cursor: pointer;
  padding: 13px 16px; font-size: 11px; color: var(--oil-muted2);
}

/* ── 주변 주유소 목록 ──────────────────────────────────────── */
.oil-near-head { display: flex; align-items: baseline; }
.oil-near-h1 {
  margin: 0; font-size: 19px; font-weight: 900; letter-spacing: -0.03em;
  color: var(--oil-ink); line-height: 1.35;
}
.oil-near-n { font-size: 15px; color: var(--oil-muted); margin-left: 4px; }

/* 고르는 줄 - 주변반경 · 유종 · 차종 */
.oil-picks { display: flex; gap: 6px; }
.oil-pick {
  flex: 1 1 0; min-width: 0; display: block; position: relative;
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 11px; padding: 6px 10px 7px;
}
.oil-pick-k {
  display: block; font-size: 10px; font-weight: 600; letter-spacing: .04em;
  color: var(--oil-muted2);
}
.oil-pick-s {
  width: 100%; border: 0; background: none; padding: 1px 16px 0 0; margin: 0;
  font-size: 13.5px; font-weight: 700; color: var(--oil-ink);
  letter-spacing: -0.02em; cursor: pointer;
  -webkit-appearance: none; appearance: none;
}
.oil-pick-s:focus { outline: none; }
.oil-pick::after {
  content: ''; position: absolute; right: 10px; bottom: 13px;
  width: 6px; height: 6px; border-right: 1.6px solid var(--oil-muted);
  border-bottom: 1.6px solid var(--oil-muted); transform: rotate(45deg);
  pointer-events: none;
}

/* ── 주유소 카드 ───────────────────────────────────────────── */
.oil-sts { display: flex; flex-direction: column; gap: 10px; }
.oil-st {
  background: var(--oil-card); border: 1px solid var(--oil-line);
  border-radius: 14px; padding: 14px 15px;
}
.oil-st-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.oil-st-name {
  font-size: 14px; font-weight: 700; color: var(--oil-ink); min-width: 0; line-height: 1.45;
}
.oil-st-tags { display: block; margin-top: 3px; }
.oil-st-tags .oil-tag:first-child { margin-left: 0; }
.oil-st-fig { flex-shrink: 0; text-align: right; }
.oil-st-price {
  display: block; font-size: 19px; font-weight: 900; color: var(--oil-ink);
  letter-spacing: -0.03em;
}
.oil-st-price i { font-style: normal; font-size: 12px; font-weight: 600; margin-left: 2px; }
.oil-st-km { display: block; font-size: 12px; color: var(--oil-muted); margin-top: 2px; }
.oil-st-line {
  margin-top: 9px; padding: 8px 11px; border-radius: 9px;
  font-size: 12.5px; line-height: 1.55;
}
.oil-st-line b { font-weight: 800; }
.oil-st-line.is-good { background: var(--oil-teal-soft); color: var(--oil-teal-dark); }
.oil-st-line.is-bad { background: var(--oil-soft); color: var(--oil-muted); }
.oil-st-line.is-base { background: var(--oil-accent-soft); color: var(--oil-accent-dark); }
.oil-st-acts { display: flex; gap: 7px; margin-top: 10px; }
.oil-st-btn {
  flex: 1 1 0; padding: 10px 0; border-radius: 10px; cursor: pointer;
  text-align: center; font-size: 12.5px; font-weight: 600;
  background: var(--oil-card); border: 1px solid var(--oil-line); color: var(--oil-ink2);
}
.oil-st-btn.is-go { background: var(--oil-ink); border-color: var(--oil-ink); color: #fff; }
.oil-st-detail { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--oil-line-soft); }
.oil-st-detail .oil-rows { margin-top: 12px; }

/* 상세보기 안의 지도 - 출발지와 주유소를 함께 찍는다 */
.oil-st-map {
  position: relative; width: 100%; height: 190px; overflow: hidden;
  border: 1px solid var(--oil-line); border-radius: 11px; background: var(--oil-soft);
}
.oil-st-map-msg {
  display: flex; align-items: center; justify-content: center; height: 100%;
  font-size: 12px; color: var(--oil-muted2);
}
.oil-map-tag {
  display: inline-block; padding: 3px 8px; border-radius: 7px;
  font-size: 11px; font-weight: 700; white-space: nowrap;
  box-shadow: 0 1px 4px rgba(0, 0, 0, .22);
}
.oil-map-tag.is-from { background: var(--oil-ink); color: #fff; }
.oil-map-tag.is-to { background: var(--oil-accent); color: #fff; }
.oil-st-why {
  margin: 11px 0 0; font-size: 11.5px; line-height: 1.7; color: var(--oil-muted);
}
.oil-st-why b { color: var(--oil-ink); font-weight: 700; }
.oil-st-caveat { color: var(--oil-muted2); }

/* 알림 */
.oil-note {
  background: #FDF6EE; border: 1px solid #F0D9BE; border-radius: 12px; padding: 12px 14px;
  font-size: 12.5px; line-height: 1.65; color: #5A4632;
}
.oil-loading { padding: 40px 0; text-align: center; color: var(--oil-muted); font-size: 13px; }
.oil-error { padding: 28px 16px; text-align: center; color: var(--oil-muted); font-size: 13px; }

/* 도식 */
.oil-diagram { margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--oil-line-soft); }
.oil-diagram svg { display: block; width: 100%; height: auto; }

@media (min-width: 620px) {
  .oil-h1 { font-size: 26px; }
  #oil-root { padding: 20px 16px; }
}

body.script:
//
/*@@OIL_CONFIG_START@@*/
window.OIL_CONFIG = {
  listPageUrl: '/',
  areaPageUrl: '/p/area.html',
  calcPageUrl: '/p/calc.html',
  reportLabelUrl: '/search/label/기름값리포트',
  dataBaseUrl: 'https://letsdoooitdo-dot.github.io/search-oil/api/',
  adClient: '',
  adSlot: '',
  /* 카카오맵 장소검색. 비어 있으면 우리 데이터(읍면동·시군구·주유소 이름)로만 찾는다.
     SDK 는 검색창을 실제로 쓸 때 그때 불러온다 - 안 쓰는 사람은 내려받지 않는다. */
  kakaoKey: 'f0e3cf8d7eda3f38469d8ab719daed3c'
};
/*@@OIL_CONFIG_END@@*/
//

//
/* 주유소찾기 - 블로그스팟 화면 분기
   주소를 보고 어떤 화면을 그릴지 정한다.
     /                        찾기 (장소 검색 / 내 주변)  ← 첫 화면
     /p/area.html?la=&ln=     그 지점 주변 주유소
     /p/area.html?r=...       동네 상세
     /p/area.html             동네 목록 + 오늘 전국 현황
     /p/calc.html             계산기
     그 외                     일반 블로그 글

   블로그스팟은 페이지를 사람이 하나씩 만들어야 해서, 한 페이지에 물음표 뒤 값으로
   여러 화면을 태운다. 페이지를 새로 만들 필요가 없다.
*/
(function () {
  'use strict';

  var cfg = window.OIL_CONFIG || {};
  var html = document.documentElement;
  var path = location.pathname.replace(/\/+$/, '') || '/';
  var qs = new URLSearchParams(location.search);

  var areaPath = (cfg.areaPageUrl || '/p/area.html').replace(/\/+$/, '');
  var calcPath = (cfg.calcPageUrl || '/p/calc.html').replace(/\/+$/, '');

  var mode = 'blog';
  if (path === '/' || path === '/index.html') mode = 'find';
  else if (path === areaPath) {
    if (qs.get('la') && qs.get('ln')) mode = 'near';
    else if (qs.get('r')) mode = 'area';
    else mode = 'browse';
  } else if (path === calcPath) mode = 'calc';

  html.classList.add('oil-mode-' + mode);
  window.OIL_MODE = mode;

  /* 탭 표시 */
  var tabs = [
    ['주유소 찾기', cfg.listPageUrl || '/'],
    ['우리 동네', cfg.areaPageUrl || '/p/area.html'],
    ['계산기', cfg.calcPageUrl || '/p/calc.html'],
    ['기름값 이야기', (cfg.reportLabelUrl || '/search/label/기름값리포트')]
  ];
  var ACTIVE = { find: 0, near: 0, area: 1, browse: 1, calc: 2, blog: 3 };
  var nav = document.getElementById('oil-tabs');
  if (nav) {
    var active = ACTIVE[mode];
    nav.innerHTML = '<ul>' + tabs.map(function (t, i) {
      return '<li><a class="' + (i === active ? 'active' : '') + '" href="' + t[1] + '">' +
        t[0] + '</a></li>';
    }).join('') + '</ul>';
  }

  /* 앱 화면이 아니면 본문 자리를 비워 공간을 차지하지 않게 한다 */
  if (mode === 'blog') {
    var root = document.getElementById('oil-root');
    if (root) root.style.display = 'none';
  }
})();

/* 주유소찾기 - 공통 (데이터 불러오기·숫자 포맷·광고·해설 문장) */
(function () {
  'use strict';

  var CFG = window.OIL_CONFIG || {};
  var OIL = window.OIL = window.OIL || {};

  OIL.cfg = CFG;

  /* ── 숫자·문자 ───────────────────────────────────────────── */
  OIL.won = function (n) { return Math.round(n).toLocaleString('ko-KR'); };
  OIL.esc = function (s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  };
  OIL.dateKo = function (iso) {
    if (!iso) return '';
    var p = iso.split('-');
    return p[0] + '년 ' + Number(p[1]) + '월 ' + Number(p[2]) + '일';
  };
  /* 받침 유무로 은/는 같은 조사를 고른다 */
  OIL.josa = function (word, pair) {
    pair = pair || '은는';
    if (!word) return pair[1];
    var ch = word.charCodeAt(word.length - 1);
    if (ch < 0xac00 || ch > 0xd7a3) return pair[1];
    return (ch - 0xac00) % 28 ? pair[0] : pair[1];
  };

  /* ── 데이터 ──────────────────────────────────────────────── */
  var cache = {};
  OIL.load = function (path) {
    if (cache[path]) return cache[path];
    var base = (CFG.dataBaseUrl || '').replace(/\/+$/, '');
    cache[path] = fetch(base + '/' + path, { cache: 'no-cache' })
      .then(function (r) {
        if (!r.ok) throw new Error(path + ' ' + r.status);
        return r.json();
      })
      .catch(function (e) { delete cache[path]; throw e; });
    return cache[path];
  };
  OIL.meta = function () { return OIL.load('meta.json'); };
  OIL.regions = function () { return OIL.load('regions.json'); };
  OIL.region = function (slug) { return OIL.load('region/' + encodeURIComponent(slug) + '.json'); };

  /* ── 화면 ────────────────────────────────────────────────── */
  OIL.root = function () { return document.getElementById('oil-root'); };
  OIL.loading = function (msg) {
    var r = OIL.root();
    if (r) r.innerHTML = '<div class="oil-loading">' + OIL.esc(msg || '불러오는 중...') + '</div>';
  };
  OIL.fail = function (e) {
    var r = OIL.root();
    if (r) {
      r.innerHTML = '<div class="oil-error">데이터를 불러오지 못했습니다.<br>' +
        '잠시 후 다시 시도해주세요.</div>';
    }
    if (window.console) console.error(e);
  };
  OIL.areaUrl = function (slug) {
    return (CFG.areaPageUrl || '/p/area.html') + '?r=' + encodeURIComponent(slug);
  };
  OIL.param = function (k) {
    return new URLSearchParams(location.search).get(k) || '';
  };

  /* ── 거리와 손익분기 ─────────────────────────────────────────
     우리 서비스의 핵심이다. "싼 집이 항상 이득은 아니다" 를 숫자로 보여준다.

     주의할 점 두 가지
       1) 좌표로 재면 직선거리다. 실제 도로는 보통 1.3배쯤 된다 - ROAD 로 보정하고
          화면에도 어림값이라고 밝힌다.
       2) 목적지가 없으면 '우회'가 아니라 '일부러 갔다 오는 것'이다. 그래서 왕복으로 센다.
          목적지 기준 진짜 우회 계산은 2차에서 붙인다.
  */
  var ROAD = 1.3;
  OIL.ROAD = ROAD;

  OIL.distKm = function (lat1, lng1, lat2, lng2) {
    var R = 6371, rad = Math.PI / 180;
    var dLat = (lat2 - lat1) * rad, dLng = (lng2 - lng1) * rad;
    var s = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
    return 2 * R * Math.asin(Math.sqrt(s));
  };

  /* price  이 주유소 가격
     base   기준 주유소 가격 (여기서 가장 가까운 집 - 아무것도 안 따지면 갔을 곳)
     km     출발지에서 이 주유소까지 직선거리
     baseKm 출발지에서 기준 주유소까지 직선거리

     기준 주유소도 어차피 가야 하므로, 무는 것은 '더 가는 거리'뿐이다.
     출발지에서의 전체 거리를 물리면 가까운 집이 공짜가 되어 늘 이긴다.
     주유하고 가던 길을 계속 간다고 보고 편도로 센다. */
  OIL.calcTrip = function (price, base, km, baseKm) {
    var car = (OIL.prefs && OIL.prefs.car()) || { kmpl: 12, usual: 30, label: '일반 승용차' };
    var L = car.usual, kmpl = car.kmpl;
    var road = km * ROAD;                        /* 화면에 보여줄 도로거리(어림) */
    var extra = Math.max(0, km - (baseKm || 0)); /* 기준보다 더 가는 직선거리 */
    var extraRoad = extra * ROAD;
    var cost = extraRoad / kmpl * price;         /* 더 가느라 쓰는 기름값 */
    var gain = (base - price) * L;               /* 싸게 넣어 아끼는 돈 */
    /* 손익분기: 기준보다 몇 km 더 가는 데까지 본전인가 (도로거리) */
    var beKm = price > 0 ? gain * kmpl / price : 0;
    return { km: km, road: road, extra: extra, extraRoad: extraRoad,
             cost: cost, gain: gain, net: gain - cost, beKm: beKm,
             L: L, kmpl: kmpl, car: car };
  };

  /* 카드에 한 줄로 넣을 판정 문구. 숫자를 늘어놓지 않는다 - 근거는 상세보기로 민다. */
  OIL.tripLine = function (t, isBase) {
    if (isBase) {
      return { cls: 'is-base', text: '여기서 <b>가장 가까운 주유소</b> · 비교 기준' };
    }
    if (t.gain === 0) {
      return { cls: 'is-bad', text: '가까운 곳과 <b>같은 가격</b>인데 더 멉니다' };
    }
    if (t.gain < 0) {
      return { cls: 'is-bad', text: '가까운 곳보다 <b>비싼데</b> 더 멀기까지 합니다' };
    }
    if (t.net > 0) {
      return { cls: 'is-good',
               text: '더 가는 ' + t.extraRoad.toFixed(1) + 'km 기름값 빼도 <b>' +
                     OIL.won(t.net) + '원 이득</b>' };
    }
    return { cls: 'is-bad',
             text: '<b>' + t.beKm.toFixed(1) + 'km까지만 이득</b>인데 ' +
                   t.extraRoad.toFixed(1) + 'km 더 갑니다' };
  };

  /* 찾아가기 - 카카오맵. API 키가 필요 없고 앱이 깔려 있으면 앱이 열린다. */
  OIL.mapUrl = function (s) {
    var name = String(s.n || '주유소').replace(/,/g, ' ');
    if (s.la && s.ln) {
      return 'https://map.kakao.com/link/to/' + encodeURIComponent(name) +
        ',' + s.la + ',' + s.ln;
    }
    return 'https://map.kakao.com/link/search/' + encodeURIComponent(name);
  };

  /* ── 광고 ────────────────────────────────────────────────── */
  OIL.adHtml = function () {
    if (!CFG.adClient || !CFG.adSlot) return '';
    return '<div class="oil-ad"><div class="oil-ad-label">광고</div>' +
      '<ins class="adsbygoogle" style="display:block"' +
      ' data-ad-client="' + CFG.adClient + '"' +
      ' data-ad-slot="' + CFG.adSlot + '"' +
      ' data-ad-format="auto" data-full-width-responsive="true"></ins></div>';
  };
  /* 광고 자리. 개발 중(ADS_ON=False)에도 자리는 남겨둬야 나중에 광고를 켤 때
     화면이 밀리지 않는다. 그래서 빈 상자를 같은 크기로 그려둔다. */
  OIL.adSlotHtml = function () {
    var ad = OIL.adHtml();
    if (ad) return ad;
    return '<div class="oil-ad is-empty"><span>광고 영역</span></div>';
  };

  /* 화면을 그린 뒤 호출한다. 아직 요청하지 않은 ins 만 채운다. */
  OIL.adFill = function () {
    try {
      var list = document.querySelectorAll('ins.adsbygoogle');
      for (var i = 0; i < list.length; i++) {
        if (list[i].getAttribute('data-adsbygoogle-status')) continue;
        (window.adsbygoogle = window.adsbygoogle || []).push({});
      }
    } catch (e) { /* 광고 차단기 등 - 화면은 그대로 둔다 */ }
  };

  OIL.render = function (html) {
    var r = OIL.root();
    if (!r) return;
    r.innerHTML = html;
    OIL.adFill();
  };

  /* ── 동네 해설 (파이썬 build_area_pages 와 같은 규칙) ──────
     s = 지금 고른 유종의 통계 {n,lo,md,hi,sp,rk}
     손익분기 거리는 고른 차종의 연비·주유량으로 계산한다 - 차종에 따라 2배까지 달라진다 */
  OIL.verdict = function (r, meta, total, s, fuelName) {
    s = s || r.g || r;
    fuelName = fuelName || '휘발유';
    var big = (meta && meta.spreadBig) || 250;
    var small = (meta && meta.spreadSmall) || 60;
    var car = (OIL.prefs && OIL.prefs.car()) || { kmpl: 12, usual: 30 };
    var L = car.usual, kmpl = car.kmpl;
    var saved = s.sp * L;
    var head, body;

    if (s.sp >= big) {
      head = r.r + '는 주유소를 고를 가치가 큽니다';
      body = '같은 ' + OIL.esc(r.r) + ' 안에서 ' + fuelName + ' 최저 ' + OIL.won(s.lo) +
        '원, 최고 ' + OIL.won(s.hi) + '원으로 <b>' + OIL.won(s.sp) + '원</b> 차이가 납니다. ' +
        '한 번에 ' + L + 'L를 넣는다면 <b>' + OIL.won(saved) + '원</b>이 갈립니다. ' +
        '아무 데나 들어가면 손해를 보는 동네입니다.';
    } else if (s.sp < small) {
      var perKm = s.md / kmpl;
      var beKm = perKm > 0 ? saved / perKm : 0;
      head = r.r + '는 어디서 넣어도 비슷합니다';
      body = '동네 안에서 가장 싼 곳과 가장 비싼 곳의 차이가 <b>' + OIL.won(s.sp) +
        '원</b>뿐입니다. 제일 싼 집을 찾아가더라도 <b>' + beKm.toFixed(1) +
        'km</b>만 더 돌면 아낀 돈이 기름값으로 사라집니다. 가는 길에 보이는 곳에서 넣으시면 됩니다.';
    } else {
      head = r.r + '는 조금 따져볼 만합니다';
      body = '동네 안 ' + fuelName + ' 가격 차이가 <b>' + OIL.won(s.sp) + '원</b>입니다. ' +
        L + 'L면 ' + OIL.won(saved) + '원 차이라, 멀리 돌아갈 정도는 아니지만 ' +
        '가는 길에 싼 곳이 있다면 들를 만합니다.';
    }

    var natMed = meta ? ((OIL.prefs && OIL.prefs.get('fuel') === 'd')
      ? meta.diesel.median : meta.gas.median) : s.md;
    var diff = s.md - natMed;
    var nat;
    if (Math.abs(diff) < 5) {
      nat = '전국 중앙값과 거의 같은 수준입니다 (전국 ' + total + '개 시군구 중 ' + s.rk + '번째로 저렴).';
    } else if (diff < 0) {
      nat = '전국 중앙값보다 <b>' + OIL.won(-diff) + '원 저렴</b>한 동네입니다 (전국 ' +
        total + '개 시군구 중 ' + s.rk + '번째).';
    } else {
      nat = '전국 중앙값보다 <b>' + OIL.won(diff) + '원 비싼</b> 동네입니다 (전국 ' +
        total + '개 시군구 중 ' + s.rk + '번째로 저렴).';
    }
    return { head: head, body: body, nat: nat };
  };

  OIL.characterLine = function (r) {
    if (!r.ac) {
      return '이 동네에는 1년 내내 최저권을 지킨 주유소가 없습니다. ' +
        '오늘 싼 곳이 다음 달에도 싸다는 보장이 없으니, 넣기 전에 매번 확인하는 편이 낫습니다.';
    }
    if (r.ac === 1) {
      return '이 동네에서 1년 내내 최저권을 지킨 주유소는 <b>단 한 곳</b>입니다. ' +
        '오늘 하루 싼 집과 계속 싼 집은 다릅니다.';
    }
    return '1년 내내 최저권을 지킨 주유소가 <b>' + r.ac + '곳</b> 있습니다. ' +
      '반대로 1년 내내 비싼 축이었던 곳도 ' + r.ap + '곳입니다.';
  };

  OIL.chev = function (color) {
    return '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="' +
      (color || '#5B666A') + '" stroke-width="2.5" aria-hidden="true">' +
      '<path d="M9 6l6 6-6 6"></path></svg>';
  };
})();

/* 주유소찾기 - 내 설정 (유종·차종·우리 동네)

   원칙: 아무것도 안 골라도 화면이 돌아간다. 고를수록 정확해진다.
   저장은 브라우저가 한다(로그인·서버 없음). 기록을 지우면 초기화된다.
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL) return;

  var KEY = 'oil.prefs';

  /* 차종별 기본값 - 파이썬 fill_amount.VEHICLE 과 같은 값 */
  var VEHICLE = {
    '경차':   { kmpl: 16, tank: 35, usual: 25, label: '경차' },
    '일반':   { kmpl: 12, tank: 60, usual: 30, label: '일반 승용차' },
    'SUV':    { kmpl: 8,  tank: 80, usual: 60, label: 'SUV' },
    '화물':   { kmpl: 9,  tank: 60, usual: 50, label: '화물차' }
  };
  var VEHICLE_ORDER = ['경차', '일반', 'SUV', '화물'];
  var FUELS = { g: '휘발유', d: '경유' };

  /* radius - 주변 주유소를 몇 km 안에서 찾을지. 사용자가 직접 고른다. */
  var RADIUS = [1, 2, 3, 4, 5, 10, 15, 20];

  var DEFAULTS = { fuel: 'g', vehicle: '일반', radius: 5,
                   home: '', work: '', last: '', spot: '', visits: 0 };

  function read() {
    try {
      var raw = localStorage.getItem(KEY);
      if (!raw) return null;
      var o = JSON.parse(raw);
      return (o && typeof o === 'object') ? o : null;
    } catch (e) { return null; }   /* 사생활 보호 모드 등 - 기본값으로 간다 */
  }

  function write(o) {
    try { localStorage.setItem(KEY, JSON.stringify(o)); } catch (e) { /* 저장 못해도 동작은 한다 */ }
  }

  var saved = read();
  var isFirst = !saved;
  var state = {};
  for (var k in DEFAULTS) state[k] = (saved && saved[k] != null) ? saved[k] : DEFAULTS[k];
  if (!VEHICLE[state.vehicle]) state.vehicle = '일반';
  if (!FUELS[state.fuel]) state.fuel = 'g';
  if (RADIUS.indexOf(state.radius) < 0) state.radius = 5;

  state.visits = (state.visits || 0) + 1;
  write(state);

  var P = OIL.prefs = {
    VEHICLE: VEHICLE,
    FUELS: FUELS,
    RADIUS: RADIUS,
    isFirstVisit: isFirst,
    get: function (k) { return k ? state[k] : state; },
    set: function (k, v) { state[k] = v; write(state); },
    car: function () { return VEHICLE[state.vehicle] || VEHICLE['일반']; },
    fuelName: function () { return FUELS[state.fuel]; },
    /* 동네 요약에서 현재 유종의 통계를 꺼낸다 */
    pick: function (region) { return region ? region[state.fuel] : null; }
  };

  /* ── 설정 바 ─────────────────────────────────────────────
     첫 방문이면 펼쳐서 보여주고, 재방문이면 한 줄로 접는다. */
  P.barHtml = function (opts) {
    opts = opts || {};
    var open = opts.open != null ? opts.open : isFirst;
    var regionName = opts.regionName || '';

    var fuelBtns = Object.keys(FUELS).map(function (f) {
      return '<button type="button" class="oil-chip' + (state.fuel === f ? ' active' : '') +
        '" data-pref="fuel" data-val="' + f + '">' + FUELS[f] + '</button>';
    }).join('');

    var carBtns = VEHICLE_ORDER.map(function (v) {
      return '<button type="button" class="oil-chip' + (state.vehicle === v ? ' active' : '') +
        '" data-pref="vehicle" data-val="' + v + '">' + VEHICLE[v].label + '</button>';
    }).join('');

    var summary = FUELS[state.fuel] + ' · ' + P.car().label +
      (regionName ? ' · ' + regionName : '');

    return '<div class="oil-prefs' + (open ? ' is-open' : '') + '" id="oil-prefs">' +
      '<button type="button" class="oil-prefs-sum" id="oil-prefs-toggle">' +
        '<span class="oil-prefs-sum-t">' + OIL.esc(summary) + '</span>' +
        '<span class="oil-prefs-sum-a">변경</span>' +
      '</button>' +
      '<div class="oil-prefs-body">' +
        '<div class="oil-prefs-row"><span class="oil-prefs-k">유종</span>' +
          '<div class="oil-sido-tabs">' + fuelBtns + '</div></div>' +
        '<div class="oil-prefs-row"><span class="oil-prefs-k">차종</span>' +
          '<div class="oil-sido-tabs">' + carBtns + '</div></div>' +
        '<div class="oil-prefs-hint">차종을 고르면 연비 ' + P.car().kmpl +
          'km/L, 1회 주유 ' + P.car().usual + 'L 로 계산합니다</div>' +
      '</div></div>';
  };

  /* 설정 바 동작 연결. onChange 로 다시 그리게 한다. */
  P.wireBar = function (onChange) {
    var box = document.getElementById('oil-prefs');
    if (!box) return;
    var toggle = document.getElementById('oil-prefs-toggle');
    if (toggle) {
      toggle.addEventListener('click', function () { box.classList.toggle('is-open'); });
    }
    box.addEventListener('click', function (e) {
      var b = e.target.closest('[data-pref]');
      if (!b) return;
      var key = b.getAttribute('data-pref');
      P.set(key, b.getAttribute('data-val'));
      if (onChange) onChange(key);
    });
  };

  /* ── 고르는 줄 (주변반경 · 유종 · 차종) ────────────────────
     주변 주유소 화면 맨 위에 붙는다. 세 가지가 전부 결과를 바꾼다.
       반경 - 몇 km 안에서 찾을지 (사용자가 갈 의향이 있는 거리)
       유종 - 휘발유가 싼 집이 경유도 싸다는 보장이 없다
       차종 - 연비에 따라 손익분기가 2배까지 달라진다
     휴대폰에서는 <select> 가 운영체제 고르개를 띄워줘서 가장 쓰기 편하다. */
  function sel(key, label, opts) {
    return '<label class="oil-pick">' +
      '<span class="oil-pick-k">' + label + '</span>' +
      '<select class="oil-pick-s" data-pref="' + key + '">' +
      opts.map(function (o) {
        return '<option value="' + o[0] + '"' +
          (String(state[key]) === String(o[0]) ? ' selected' : '') + '>' + o[1] + '</option>';
      }).join('') + '</select></label>';
  }

  P.pickerHtml = function () {
    return '<div class="oil-picks">' +
      sel('radius', '주변반경', RADIUS.map(function (k) { return [k, k + 'km']; })) +
      sel('fuel', '유종', Object.keys(FUELS).map(function (f) { return [f, FUELS[f]]; })) +
      sel('vehicle', '차종', VEHICLE_ORDER.map(function (v) { return [v, VEHICLE[v].label]; })) +
      '</div>';
  };

  P.wirePicker = function (onChange) {
    var box = document.querySelector('.oil-picks');
    if (!box) return;
    box.addEventListener('change', function (e) {
      var s = e.target.closest('[data-pref]');
      if (!s) return;
      var key = s.getAttribute('data-pref');
      P.set(key, key === 'radius' ? parseInt(s.value, 10) : s.value);
      if (onChange) onChange(key);
    });
  };

  /* ── 내 위치 ─────────────────────────────────────────────
     휴대폰이 알려준 좌표에서 가장 가까운 동네를 고른다.
     주소는 알 수 없고 알 필요도 없다 - 시군구까지면 충분하다. */
  function distKm(a, b, c, d) {
    var R = 6371, rad = Math.PI / 180;
    var dLat = (c - a) * rad, dLng = (d - b) * rad;
    var s = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(a * rad) * Math.cos(c * rad) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
    return 2 * R * Math.asin(Math.sqrt(s));
  }

  P.nearest = function (lat, lng, items) {
    var best = null, bestD = Infinity;
    for (var i = 0; i < items.length; i++) {
      var r = items[i];
      if (r.la == null) continue;
      var d = distKm(lat, lng, r.la, r.ln);
      if (d < bestD) { bestD = d; best = r; }
    }
    return best ? { region: best, km: bestD } : null;
  };

  /* 읍·면·동까지 찾는다. 주유소가 있는 동만 데이터에 있어 근사치이므로
     화면에는 '부근'이라고 밝힌다. */
  function nearestDong(lat, lng) {
    return OIL.load('geo.json').then(function (geo) {
      var best = null, bestD = Infinity;
      for (var i = 0; i < geo.items.length; i++) {
        var g = geo.items[i];
        var d = distKm(lat, lng, g.la, g.ln);
        if (d < bestD) { bestD = d; best = g; }
      }
      /* 너무 멀면(15km 초과) 엉뚱한 동을 말하게 되므로 쓰지 않는다 */
      return (best && bestD <= 15) ? { dong: best, km: bestD } : null;
    }).catch(function () { return null; });
  }

  /* onDone(결과, 오류메시지) — 결과에 region 과 spot(읍면동)이 들어온다 */
  P.locate = function (onDone) {
    if (!navigator.geolocation) {
      onDone(null, '이 브라우저는 위치 기능을 지원하지 않습니다.');
      return;
    }
    navigator.geolocation.getCurrentPosition(function (pos) {
      var lat = pos.coords.latitude, lng = pos.coords.longitude;
      Promise.all([OIL.regions(), nearestDong(lat, lng)]).then(function (a) {
        var reg = a[0], spot = a[1];
        var hit = P.nearest(lat, lng, reg.items);
        if (!hit) { onDone(null, '가까운 동네를 찾지 못했습니다.'); return; }
        /* 동을 찾았고 그 동이 다른 시군구에 속하면, 동 쪽 시군구를 믿는다 */
        if (spot && spot.dong.r !== hit.region.r) {
          for (var i = 0; i < reg.items.length; i++) {
            if (reg.items[i].r === spot.dong.r) { hit.region = reg.items[i]; break; }
          }
        }
        hit.spot = spot;
        hit.accuracy = pos.coords.accuracy;
        onDone(hit, null);
      }).catch(function () { onDone(null, '데이터를 불러오지 못했습니다.'); });
    }, function (err) {
      var msg = '위치를 가져오지 못했습니다.';
      if (err && err.code === 1) msg = '위치 권한이 거부되었습니다. 아래에서 직접 선택해주세요.';
      else if (err && err.code === 3) msg = '위치 확인이 오래 걸립니다. 아래에서 직접 선택해주세요.';
      onDone(null, msg);
    }, { enableHighAccuracy: false, timeout: 8000, maximumAge: 600000 });
  };

  P.locateBtnHtml = function () {
    return '<button type="button" class="oil-locate" id="oil-locate">' +
      '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
      'stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="3"></circle>' +
      '<path d="M12 2v3M12 19v3M2 12h3M19 12h3"></path></svg>' +
      '<span>내 위치로 우리 동네 찾기</span></button>' +
      '<div class="oil-locate-msg" id="oil-locate-msg"></div>';
  };

  /* 찾은 위치를 사람이 읽을 문장으로. 예: "충남 천안시 신당동 부근" */
  P.spotText = function (hit) {
    if (!hit) return '';
    if (hit.spot) return hit.spot.dong.r + ' ' + hit.spot.dong.d + ' 부근';
    return hit.region.r + ' 부근';
  };

  P.wireLocate = function () {
    var btn = document.getElementById('oil-locate');
    var msg = document.getElementById('oil-locate-msg');
    if (!btn) return;
    btn.addEventListener('click', function () {
      btn.disabled = true;
      msg.textContent = '위치를 확인하는 중...';
      P.locate(function (hit, err) {
        if (err) { btn.disabled = false; msg.textContent = err; return; }
        var where = P.spotText(hit);
        msg.textContent = where + ' — ' + hit.region.r + ' 기름값을 봅니다';
        P.set('last', hit.region.sl);
        P.set('spot', where);      /* 동네 화면에서 "현위치"로 보여준다 */
        location.href = OIL.areaUrl(hit.region.sl);
      });
    });
  };
})();

/* 주유소찾기 - 장소 검색과 저장

   검색은 카카오맵을 쓴다. 키가 없거나 카카오가 답이 없으면 우리 데이터로 찾는다
   (읍·면·동 2,722곳 + 시·군·구 230곳). 둘 다 좌표를 돌려주므로 뒤 계산은 같다.

   저장은 브라우저가 한다. 로그인도 서버도 없다.
   기기마다 따로 남고 사용기록을 지우면 같이 날아간다 - 없어도 서비스는 돌아가야 한다.

   장소 하나는 { n: 이름, a: 주소, la: 위도, ln: 경도 } 로만 다룬다.
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL) return;

  var KEY = 'oil.places';
  var MAX_RECENT = 8;

  function read() {
    try {
      var o = JSON.parse(localStorage.getItem(KEY));
      return (o && typeof o === 'object') ? o : {};
    } catch (e) { return {}; }   /* 시크릿 모드 등 - 빈 걸로 간다 */
  }
  function save() {
    try { localStorage.setItem(KEY, JSON.stringify(store)); } catch (e) { /* 못 담아도 동작은 한다 */ }
  }

  var store = read();
  if (!Array.isArray(store.recent)) store.recent = [];

  var PL = OIL.place = {};

  /* ── 저장 ────────────────────────────────────────────────── */
  PL.slot = function (name) { return store[name] || null; };          /* 'home' | 'work' */
  PL.setSlot = function (name, p) { store[name] = p; save(); };
  PL.clearSlot = function (name) { delete store[name]; save(); };

  PL.recent = function () { return store.recent; };
  PL.remember = function (p) {
    if (!p) return;
    store.recent = store.recent.filter(function (x) {
      return !(x.n === p.n && x.a === p.a);
    });
    store.recent.unshift(p);
    store.recent = store.recent.slice(0, MAX_RECENT);
    save();
  };
  PL.forget = function (i) { store.recent.splice(i, 1); save(); };
  PL.clearRecent = function () { store.recent = []; save(); };

  /* 고른 장소를 다음 화면으로 넘긴다 */
  PL.url = function (p) {
    return (OIL.cfg.areaPageUrl || '/p/area.html') +
      '?la=' + p.la.toFixed(5) + '&ln=' + p.ln.toFixed(5) +
      '&q=' + encodeURIComponent(p.n);
  };

  /* ── 카카오 SDK ──────────────────────────────────────────────
     검색창을 실제로 쓸 때 그때 부른다. 안 쓰는 사람은 내려받지 않는다. */
  var sdk = null;
  function loadSdk() {
    if (sdk) return sdk;
    var key = OIL.cfg.kakaoKey;
    if (!key) {
      sdk = Promise.reject(new Error('kakaoKey 없음'));
      return sdk;
    }
    sdk = new Promise(function (ok, no) {
      var s = document.createElement('script');
      s.src = 'https://dapi.kakao.com/v2/maps/sdk.js?appkey=' +
        encodeURIComponent(key) + '&libraries=services&autoload=false';
      s.onload = function () {
        try { window.kakao.maps.load(function () { ok(window.kakao); }); }
        catch (e) { no(e); }
      };
      s.onerror = function () { no(new Error('SDK 로드 실패')); };
      document.head.appendChild(s);
    });
    return sdk;
  }

  PL.hasKakao = function () { return !!OIL.cfg.kakaoKey; };
  PL.sdk = loadSdk;     /* 지도를 그릴 때도 같은 SDK 를 쓴다 - 한 번만 받는다 */

  /* ── 검색 ────────────────────────────────────────────────── */
  function fromKakao(q) {
    return loadSdk().then(function (kakao) {
      return new Promise(function (ok) {
        new kakao.maps.services.Places().keywordSearch(q, function (data, status) {
          if (status !== kakao.maps.services.Status.OK || !data || !data.length) {
            ok([]);
            return;
          }
          ok(data.slice(0, 15).map(function (d) {
            return {
              n: d.place_name,
              a: d.road_address_name || d.address_name || '',
              la: parseFloat(d.y), ln: parseFloat(d.x)
            };
          }));
        });
      });
    });
  }

  /* 카카오가 없을 때. 동네 이름만 찾을 수 있다. */
  PL.searchLocal = function (q) {
    return Promise.all([OIL.regions(), OIL.load('geo.json')]).then(function (a) {
      var regions = a[0].items, geo = a[1].items, out = [];
      for (var i = 0; i < regions.length && out.length < 15; i++) {
        var r = regions[i];
        if (r.la != null && r.r.indexOf(q) >= 0) {
          out.push({ n: r.r, a: '시·군·구', la: r.la, ln: r.ln });
        }
      }
      for (var j = 0; j < geo.length && out.length < 15; j++) {
        var g = geo[j];
        if (g.d.indexOf(q) >= 0) out.push({ n: g.d, a: g.r, la: g.la, ln: g.ln });
      }
      return out;
    }).catch(function () { return []; });
  };

  PL.search = function (q) {
    q = String(q || '').trim();
    if (q.length < 1) return Promise.resolve([]);
    if (!PL.hasKakao()) return PL.searchLocal(q);
    return fromKakao(q)
      .then(function (list) { return list.length ? list : PL.searchLocal(q); })
      .catch(function () { return PL.searchLocal(q); });
  };
})();

/* 주유소찾기 - 첫 화면(분기)과 장소 검색 화면

   첫 화면은 기능 두 개만 둔다.
     1) 장소명 검색  -> 그 장소 주변 주유소
     2) 내 주변      -> 현재 위치 주변 주유소
   둘 다 출발점만 다를 뿐 같은 결과 화면으로 간다.

   검색 화면은 페이지를 바꾸지 않고 덮는다. 휴대폰 뒤로가기로 닫히도록
   history 에 한 칸 넣어둔다.
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL || window.OIL_MODE !== 'find') return;

  var esc = OIL.esc, won = OIL.won;
  var P = OIL.prefs, PL = OIL.place;

  var PIN = '<svg class="oil-pin" width="15" height="15" viewBox="0 0 24 24" fill="none" ' +
    'stroke="currentColor" stroke-width="1.8" aria-hidden="true">' +
    '<path d="M12 21s7-6.2 7-11a7 7 0 1 0-14 0c0 4.8 7 11 7 11z"></path>' +
    '<circle cx="12" cy="10" r="2.4"></circle></svg>';

  /* ── 첫 화면 ─────────────────────────────────────────────── */
  function renderFind(meta, reg) {
    /* 전에 위치를 찾아둔 적이 있으면 그 동네 가격을 미리 보여준다 */
    var lastSlug = P ? P.get('last') : '';
    var spot = P ? P.get('spot') : '';
    var near = null;
    if (lastSlug) {
      for (var i = 0; i < reg.items.length; i++) {
        if (reg.items[i].sl === lastSlug) { near = reg.items[i]; break; }
      }
    }

    var html = '<div class="oil-find">';

    /* 1. 장소명 검색 */
    html += '<section class="oil-find-sec">' +
      '<h2 class="oil-find-h">장소명으로 찾기</h2>' +
      '<button type="button" class="oil-fakein" id="oil-open-search">' +
        '<span>장소명을 검색해 주세요</span>' +
        '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
        'stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle>' +
        '<path d="M20 20l-3.5-3.5"></path></svg>' +
      '</button>' +
      '<p class="oil-find-hint">회사·아파트·역 이름으로 찾을 수 있습니다</p>' +
      '</section>';

    /* 2. 내 주변 */
    var sub;
    if (near) {
      var g = near.g, d = near.d;
      sub = '<span class="oil-near-price">' +
        (g ? '<b>휘발유</b> ' + won(g.lo) + '원' : '') +
        (d ? '<b>경유</b> ' + won(d.lo) + '원' : '') + '</span>' +
        '<span class="oil-near-where">' + esc(spot || near.r) + ' 기준</span>';
    } else {
      sub = '<span class="oil-near-where">위치를 켜면 주변 최저가를 바로 보여드립니다</span>';
    }

    html += '<section class="oil-find-sec">' +
      '<h2 class="oil-find-h">내 주변에서 찾기</h2>' +
      '<button type="button" class="oil-near-btn" id="oil-near">' +
        '<span class="oil-near-l">' + PIN +
          '<span><span class="oil-near-t">내 주변 주유소 찾기</span>' + sub + '</span></span>' +
        OIL.chev('#fff') +
      '</button>' +
      '<div class="oil-locate-msg" id="oil-locate-msg"></div>' +
      '</section>';

    /* 3. 광고 자리 */
    html += OIL.adSlotHtml();

    html += '</div>';

    OIL.render(html);
    document.title = '주유소찾기 - 내 주변 기름값 싼 주유소';

    document.getElementById('oil-open-search')
      .addEventListener('click', function () { openSheet(); });
    document.getElementById('oil-near')
      .addEventListener('click', goNear);
  }

  /* 내 주변 - 위치를 새로 받아서 결과 화면으로 */
  function goNear() {
    var btn = document.getElementById('oil-near');
    var msg = document.getElementById('oil-locate-msg');
    if (!navigator.geolocation) {
      msg.textContent = '이 브라우저는 위치 기능을 지원하지 않습니다. 장소명으로 찾아주세요.';
      return;
    }
    btn.disabled = true;
    msg.textContent = '위치를 확인하는 중...';
    navigator.geolocation.getCurrentPosition(function (pos) {
      var la = pos.coords.latitude, ln = pos.coords.longitude;
      location.href = (OIL.cfg.areaPageUrl || '/p/area.html') +
        '?la=' + la.toFixed(5) + '&ln=' + ln.toFixed(5) + '&me=1';
    }, function (err) {
      btn.disabled = false;
      msg.textContent = (err && err.code === 1)
        ? '위치 권한이 거부되었습니다. 위 검색창에 동네나 장소 이름을 넣어주세요.'
        : '위치 확인이 오래 걸립니다. 위 검색창에 동네나 장소 이름을 넣어주세요.';
    }, { enableHighAccuracy: true, timeout: 8000, maximumAge: 300000 });
  }

  /* ── 검색 화면 ───────────────────────────────────────────── */
  var sheet = null, input = null, body = null;
  var pending = '';       /* '집으로 지정' 같은 상태. 'home' | 'work' | '' */
  var timer = null, seq = 0;

  function openSheet(slot) {
    pending = slot || '';
    if (!sheet) buildSheet();
    sheet.classList.add('is-open');
    document.body.classList.add('oil-noscroll');
    input.value = '';
    drawIdle();
    /* 휴대폰 뒤로가기로 닫히게 한 칸 넣어둔다 */
    try { history.pushState({ oilSheet: 1 }, '', location.href); } catch (e) { }
    setTimeout(function () { input.focus(); }, 30);
  }

  function closeSheet(fromPop) {
    if (!sheet || !sheet.classList.contains('is-open')) return;
    sheet.classList.remove('is-open');
    document.body.classList.remove('oil-noscroll');
    pending = '';
    if (!fromPop) {
      try { if (history.state && history.state.oilSheet) history.back(); } catch (e) { }
    }
  }

  window.addEventListener('popstate', function () { closeSheet(true); });

  function buildSheet() {
    sheet = document.createElement('div');
    sheet.className = 'oil-sheet';
    sheet.innerHTML =
      '<div class="oil-sheet-bar">' +
        '<button type="button" class="oil-sheet-ico" id="oil-sheet-back" aria-label="닫기">' +
          '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
          'stroke-width="2"><path d="M15 6l-6 6 6 6"></path></svg></button>' +
        '<input class="oil-sheet-in" id="oil-sheet-in" type="search" ' +
          'placeholder="장소명을 검색해 주세요" autocomplete="off" ' +
          'enterkeyhint="search" aria-label="장소 검색">' +
        '<button type="button" class="oil-sheet-ico" id="oil-sheet-clear" aria-label="지우기">' +
          '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
          'stroke-width="2"><path d="M6 6l12 12M18 6L6 18"></path></svg></button>' +
      '</div><div class="oil-sheet-body" id="oil-sheet-body"></div>';
    document.body.appendChild(sheet);

    input = sheet.querySelector('#oil-sheet-in');
    body = sheet.querySelector('#oil-sheet-body');

    sheet.querySelector('#oil-sheet-back').addEventListener('click', function () { closeSheet(); });
    sheet.querySelector('#oil-sheet-clear').addEventListener('click', function () {
      input.value = ''; drawIdle(); input.focus();
    });

    /* 타이핑이 멈추고 0.3초 뒤에 찾는다 - 글자마다 부르지 않는다 */
    input.addEventListener('input', function () {
      var q = input.value.trim();
      clearTimeout(timer);
      if (!q) { drawIdle(); return; }
      timer = setTimeout(function () { doSearch(q); }, 300);
    });

    body.addEventListener('click', onBodyClick);
  }

  function slotChip(name, label) {
    var p = PL.slot(name);
    if (!p) {
      return '<button type="button" class="oil-slot is-empty" data-setslot="' + name + '">' +
        '＋ ' + label + '</button>';
    }
    return '<span class="oil-slot"><button type="button" class="oil-slot-go" data-go=\'' +
      esc(JSON.stringify(p)) + '\'>' + label + ' · ' + esc(p.n) + '</button>' +
      '<button type="button" class="oil-slot-x" data-delslot="' + name +
      '" aria-label="' + label + ' 해제">✕</button></span>';
  }

  /* 검색어가 없을 때 - 집·회사·최근 검색 */
  function drawIdle() {
    var html = '';
    if (pending) {
      html += '<div class="oil-sheet-note">' +
        (pending === 'home' ? '집' : '회사') + '으로 지정할 장소를 검색해주세요</div>';
    }
    html += '<div class="oil-slots">' + slotChip('home', '집') + slotChip('work', '회사') + '</div>';

    var rec = PL.recent();
    html += '<div class="oil-sheet-head"><span>최근 검색</span>' +
      (rec.length ? '<button type="button" class="oil-sheet-clearall" id="oil-clearall">' +
        '검색기록 전체 삭제</button>' : '') + '</div>';

    if (!rec.length) {
      html += '<div class="oil-sheet-empty">최근 검색한 장소가 없습니다</div>';
    } else {
      html += '<div class="oil-hits">' + rec.map(function (p, i) {
        return '<div class="oil-hit"><button type="button" class="oil-hit-go" data-go=\'' +
          esc(JSON.stringify(p)) + '\'>' + PIN + '<span><b>' + esc(p.n) + '</b>' +
          (p.a ? '<i>' + esc(p.a) + '</i>' : '') + '</span></button>' +
          '<button type="button" class="oil-hit-x" data-forget="' + i +
          '" aria-label="삭제">✕</button></div>';
      }).join('') + '</div>';
    }
    body.innerHTML = html;
  }

  function doSearch(q) {
    var my = ++seq;
    body.innerHTML = '<div class="oil-sheet-empty">찾는 중...</div>';
    PL.search(q).then(function (list) {
      if (my !== seq) return;      /* 그 사이 더 친 글자가 있으면 버린다 */
      if (!list.length) {
        body.innerHTML = '<div class="oil-sheet-empty">검색 결과가 없습니다<br>' +
          '<span>동네 이름(예: 평택, 불당동)으로도 찾을 수 있습니다</span></div>';
        return;
      }
      body.innerHTML = '<div class="oil-sheet-head"><span>검색 결과</span></div>' +
        '<div class="oil-hits">' + list.map(function (p) {
          return '<div class="oil-hit"><button type="button" class="oil-hit-go" data-go=\'' +
            esc(JSON.stringify(p)) + '\'>' + PIN + '<span><b>' + esc(p.n) + '</b>' +
            (p.a ? '<i>' + esc(p.a) + '</i>' : '') + '</span></button></div>';
        }).join('') + '</div>';
    });
  }

  function onBodyClick(e) {
    var t = e.target;

    var clearAll = t.closest('#oil-clearall');
    if (clearAll) { PL.clearRecent(); drawIdle(); return; }

    var forget = t.closest('[data-forget]');
    if (forget) { PL.forget(+forget.getAttribute('data-forget')); drawIdle(); return; }

    var setSlot = t.closest('[data-setslot]');
    if (setSlot) { pending = setSlot.getAttribute('data-setslot'); drawIdle(); input.focus(); return; }

    var delSlot = t.closest('[data-delslot]');
    if (delSlot) { PL.clearSlot(delSlot.getAttribute('data-delslot')); drawIdle(); return; }

    var go = t.closest('[data-go]');
    if (go) {
      var p;
      try { p = JSON.parse(go.getAttribute('data-go')); } catch (err) { return; }
      if (pending) { PL.setSlot(pending, p); pending = ''; }
      PL.remember(p);
      location.href = PL.url(p);
    }
  }

  /* ── 시작 ────────────────────────────────────────────────── */
  OIL.loading();
  Promise.all([OIL.meta(), OIL.regions()])
    .then(function (a) { renderFind(a[0], a[1]); })
    .catch(OIL.fail);
})();

/* 주유소찾기 - 어떤 지점 주변의 주유소 목록

   들어오는 주소:  /p/area.html?la=37.038&ln=127.056&q=삼성전자 평택캠퍼스
                  /p/area.html?la=..&ln=..&me=1        (내 위치)

   순서는 가격순이 아니라 '실질 이득순'이다. 이게 오피넷과 다른 유일한 지점이고,
   사람들이 우리를 쓸 이유다. 싼 집이 멀면 기름값으로 다 까먹는다.

   비교 기준은 '여기서 가장 가까운 주유소'다. 거기서 넣는 대신 이 집까지 가면
   얼마가 남는지를 센다. 기준점이 없으면 '이득'이라는 말 자체가 성립하지 않는다.
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL || window.OIL_MODE !== 'near') return;

  var esc = OIL.esc, won = OIL.won;
  var P = OIL.prefs, PL = OIL.place;

  /* 반경은 사용자가 고른다(1~20km). 자료는 가장 넓은 경우에 맞춰 한 번만 받아두고
     반경을 바꿀 때는 다시 받지 않고 걸러내기만 한다. */
  var MAX_RADIUS = 20;
  var NEAR_REGION = 35;   /* 시군구 경계 문제 - 중심이 이 안에 있는 동네를 함께 본다 */
  var MAX_REGION = 4;
  var SHOW = 20;

  function fuel() { return P ? P.get('fuel') : 'g'; }
  function fuelName() { return P ? P.fuelName() : '휘발유'; }
  function radius() { return P ? P.get('radius') : 5; }
  function price(s) { return fuel() === 'd' ? s.d : s.g; }

  var la = parseFloat(OIL.param('la'));
  var ln = parseFloat(OIL.param('ln'));
  var qname = OIL.param('q');
  var isMe = OIL.param('me') === '1';
  var placeName = isMe ? '내 위치' : (qname || '선택한 장소');

  /* ── 데이터 모으기 ───────────────────────────────────────────
     시군구 하나만 보면 경계 바로 건너편의 더 싼 집을 놓친다.
     그래서 가까운 동네 몇 곳을 같이 불러 합친다. */
  function collect(reg) {
    var near = reg.items
      .filter(function (r) { return r.la != null; })
      .map(function (r) {
        return { r: r, km: OIL.distKm(la, ln, r.la, r.ln) };
      })
      .filter(function (x) { return x.km <= NEAR_REGION; })
      .sort(function (a, b) { return a.km - b.km; })
      .slice(0, MAX_REGION);

    if (!near.length) return Promise.resolve({ stations: [], regions: [] });

    return Promise.all(near.map(function (x) {
      return OIL.region(x.r.sl).catch(function () { return null; });
    })).then(function (list) {
      var out = [];
      list.forEach(function (detail, i) {
        if (!detail) return;
        (detail.stations || []).forEach(function (s) {
          if (s.la == null) return;
          var km = OIL.distKm(la, ln, s.la, s.ln);
          if (km > MAX_RADIUS) return;
          s._km = km;
          s._region = near[i].r.r;
          out.push(s);
        });
      });
      return { stations: out, regions: near.map(function (x) { return x.r; }) };
    });
  }

  /* ── 한 곳 카드 ──────────────────────────────────────────── */
  function card(s, i, baseName) {
    var p = price(s);
    var t = s._trip;
    var line = OIL.tripLine(t, s._isBase);

    var tags = '';
    if (s.s) tags += '<span class="oil-tag">셀프</span>';
    if (s.b) tags += '<span class="oil-tag">' + esc(s.b) + '</span>';
    if (s.c === '늘 최저권') tags += '<span class="oil-badge is-low">1년 내내 최저권</span>';
    else if (s.c === '늘 최고권') tags += '<span class="oil-badge is-high">오늘만 쌈</span>';

    return '<article class="oil-st">' +
      '<div class="oil-st-top">' +
        '<span class="oil-st-name">' + esc(s.n) + '<span class="oil-st-tags">' + tags + '</span></span>' +
        '<span class="oil-st-fig">' +
          '<b class="oil-st-price">' + won(p) + '<i>원</i></b>' +
          '<span class="oil-st-km">약 ' + t.road.toFixed(1) + 'km</span>' +
        '</span>' +
      '</div>' +
      '<div class="oil-st-line ' + line.cls + '">' + line.text + '</div>' +
      '<div class="oil-st-acts">' +
        '<button type="button" class="oil-st-btn" data-detail="' + i + '">상세보기</button>' +
        '<a class="oil-st-btn is-go" href="' + OIL.mapUrl(s) + '" ' +
          'target="_blank" rel="noopener">찾아가기</a>' +
      '</div>' +
      '<div class="oil-st-detail" id="oil-det-' + i + '" hidden>' + detail(s, i, baseName) + '</div>' +
      '</article>';
  }

  function detail(s, i, baseName) {
    var t = s._trip;
    /* 지도는 상세보기를 누를 때 그린다. 안 누른 사람은 내려받지 않는다. */
    var map = (PL && PL.hasKakao() && s.la != null)
      ? '<div class="oil-st-map" id="oil-map-' + i + '"></div>' : '';
    var fuels = [];
    if (s.g) fuels.push(['휘발유', s.g]);
    if (s.d) fuels.push(['경유', s.d]);
    if (s.p) fuels.push(['고급휘발유', s.p]);
    if (s.k) fuels.push(['실내등유', s.k]);

    var html = map + '<div class="oil-rows">';
    fuels.forEach(function (f) {
      html += '<div class="oil-row"><span class="oil-row-k">' + f[0] + '</span>' +
        '<span class="oil-row-v">' + won(f[1]) + '원</span></div>';
    });
    html += '<div class="oil-row"><span class="oil-row-k">주소</span>' +
      '<span class="oil-row-v" style="font-weight:500;">' + esc(s.a || '-') + '</span></div>';
    if (s.t) {
      html += '<div class="oil-row"><span class="oil-row-k">전화</span>' +
        '<span class="oil-row-v"><a href="tel:' + esc(s.t) + '">' + esc(s.t) + '</a></span></div>';
    }
    html += '<div class="oil-row"><span class="oil-row-k">상표</span>' +
      '<span class="oil-row-v" style="font-weight:500;">' + esc(s.b || '-') +
      (s.s ? ' · 셀프' : '') + '</span></div>';
    html += '</div>';

    /* 왜 이런 판정이 나왔는지 - 숨기지 않고 밝힌다 */
    html += '<p class="oil-st-why">' +
      '여기서 직선 ' + t.km.toFixed(1) + 'km → 도로 약 ' + t.road.toFixed(1) + 'km' +
      (s._isBase
        ? '<br>가장 가까운 주유소라 이곳을 비교 기준으로 씁니다.'
        : '<br>기준(' + esc(baseName) + ')보다 <b>' + t.extraRoad.toFixed(1) + 'km 더</b> 갑니다' +
          '<br>' + t.car.label + ' ' + t.kmpl + 'km/L · ' + t.L + 'L 주유 기준<br>' +
          '아끼는 돈 ' + won(t.gain) + '원 − 더 가는 기름값 ' + won(t.cost) + '원 = ' +
          '<b>' + (t.net >= 0 ? '+' : '') + won(t.net) + '원</b>') +
      '<br><span class="oil-st-caveat">직선거리에 1.3배를 곱한 어림값입니다. ' +
      '실제 길은 더 돌 수 있습니다.</span></p>';

    if (s.c === '늘 최저권') {
      html += '<p class="oil-st-why">이 주유소는 최근 1년 동안 동네 최저권을 지켰습니다. ' +
        '오늘만 싼 곳이 아닙니다.</p>';
    } else if (s.c === '늘 최고권') {
      html += '<p class="oil-st-why">이 주유소는 평소 동네에서 비싼 축입니다. ' +
        '오늘 싼 건 일시적일 수 있습니다.</p>';
    }
    return html;
  }

  /* ── 화면 ────────────────────────────────────────────────── */
  function render(meta, data) {
    var rad = radius();
    /* 고른 반경은 화면에 보여주는 거리(도로 어림)와 같은 잣대여야 한다.
       직선거리로 거르면 "5km 선택"인데 목록에 "약 6.5km"가 나와 어긋난다. */
    var all = data.stations.filter(function (s) {
      return price(s) && s._km * OIL.ROAD <= rad;
    });

    var html = '<div class="oil-stack">';

    /* 머리말 - 장소 이름과 찾은 개수 */
    html += '<div class="oil-near-head">' +
      '<h1 class="oil-near-h1">' + esc(placeName) + ' 주변 주유소' +
      '<span class="oil-near-n">(' + all.length + ')</span></h1></div>';

    /* 고르는 줄 - 반경 · 유종 · 차종 */
    if (P) html += P.pickerHtml();

    if (!all.length) {
      html += '<div class="oil-note">' + esc(placeName) + ' 반경 <b>' + rad +
        'km</b> 안에 ' + fuelName() + ' 파는 주유소가 없습니다. ' +
        '위에서 반경을 넓혀보세요.</div>' +
        '<a class="oil-btn" href="' + (OIL.cfg.listPageUrl || '/') + '">' +
        '<span>다른 장소로 찾기</span>' + OIL.chev('#fff') + '</a></div>';
      OIL.render(html);
      if (P) P.wirePicker(function () { render(meta, data); });
      return;
    }

    /* 기준 = 여기서 가장 가까운 주유소. 아무것도 안 따지면 갔을 곳이다. */
    var base = all.reduce(function (a, b) { return b._km < a._km ? b : a; });
    var basePrice = price(base);

    all.forEach(function (s) {
      s._isBase = (s === base);
      s._trip = OIL.calcTrip(price(s), basePrice, s._km, base._km);
    });

    var list = all.slice().sort(function (a, b) {
      if (b._trip.net !== a._trip.net) return b._trip.net - a._trip.net;
      return a._km - b._km;
    }).slice(0, SHOW);

    var best = list[0];
    var lead = (best._isBase || best._trip.net <= 0)
      ? '반경 ' + rad + 'km 안에서는 <b>가장 가까운 곳</b>에서 넣는 게 낫습니다. ' +
        '더 싼 집이 있어도 더 가는 기름값이 그보다 큽니다.'
      : '맨 위 주유소까지 더 가는 기름값을 빼고도 <b>' + won(best._trip.net) +
        '원</b>이 남습니다. 가격만 싼 순서가 아니라 실제로 남는 순서입니다.';
    html += '<p class="oil-lead" style="margin-top:0;">' + lead + '</p>';

    html += OIL.adSlotHtml();

    html += '<div class="oil-sts">' + list.map(function (s, i) {
      return card(s, i, base.n);
    }).join('') + '</div>';

    if (all.length > list.length) {
      html += '<p class="oil-p" style="font-size:12px;color:var(--oil-muted);text-align:center;">' +
        '반경 ' + rad + 'km 안 ' + all.length + '곳 중 남는 순서로 ' + list.length +
        '곳을 보여드립니다</p>';
    }

    html += '<a class="oil-btn" href="' + (OIL.cfg.listPageUrl || '/') + '">' +
      '<span>다른 장소로 찾기</span>' + OIL.chev('#fff') + '</a>';

    html += '<p class="oil-p" style="font-size:11.5px;color:var(--oil-muted);">' +
      OIL.dateKo(meta.date) + ' ' + fuelName() + ' 실제 판매가 · 출처 오피넷 · ' +
      '거리는 직선거리에 1.3배를 곱한 어림값입니다</p></div>';

    OIL.render(html);
    document.title = placeName + ' 주변 주유소 최저가 - 주유소찾기';

    shown = list;
    if (P) P.wirePicker(function () { render(meta, data); });
    wireDetail();
  }

  /* ── 상세보기 펼치기 · 지도 ────────────────────────────────── */
  var shown = [];
  var wired = false;

  function wireDetail() {
    if (wired) return;          /* 다시 그릴 때마다 붙이면 한 번 눌러 두 번 열린다 */
    wired = true;
    OIL.root().addEventListener('click', function (e) {
      var b = e.target.closest('[data-detail]');
      if (!b) return;
      var i = b.getAttribute('data-detail');
      var box = document.getElementById('oil-det-' + i);
      if (!box) return;
      box.hidden = !box.hidden;
      b.textContent = box.hidden ? '상세보기' : '접기';
      if (!box.hidden) drawMap(i);
    });
  }

  /* 출발한 곳과 그 주유소를 한 지도에 같이 찍는다.
     "어느 방향으로 얼마나 더 가는지"가 눈에 보여야 판정이 납득된다. */
  function drawMap(i) {
    var el = document.getElementById('oil-map-' + i);
    var s = shown[i];
    if (!el || !s || el.getAttribute('data-ready')) return;
    el.setAttribute('data-ready', '1');
    el.innerHTML = '<div class="oil-st-map-msg">지도를 불러오는 중...</div>';

    PL.sdk().then(function (kakao) {
      el.innerHTML = '';
      var from = new kakao.maps.LatLng(la, ln);
      var to = new kakao.maps.LatLng(s.la, s.ln);
      var map = new kakao.maps.Map(el, { center: from, level: 5 });
      map.setZoomable(false);        /* 목록 안이라 손가락 확대는 막는다 */

      var bounds = new kakao.maps.LatLngBounds();
      bounds.extend(from);
      bounds.extend(to);
      map.setBounds(bounds, 46, 30, 46, 30);

      new kakao.maps.Polyline({
        map: map, path: [from, to], strokeWeight: 3,
        strokeColor: '#D96206', strokeOpacity: 0.9, strokeStyle: 'shortdash'
      });
      new kakao.maps.Marker({ map: map, position: to });
      new kakao.maps.CustomOverlay({
        map: map, position: from, yAnchor: 0.5,
        content: '<span class="oil-map-tag is-from">' + esc(placeName) + '</span>'
      });
      new kakao.maps.CustomOverlay({
        map: map, position: to, yAnchor: 2.3,
        content: '<span class="oil-map-tag is-to">' + esc(s.n) + '</span>'
      });
      /* 접혀 있던 자리에 그리면 크기를 잘못 잡는 경우가 있다 */
      setTimeout(function () { map.relayout(); map.setBounds(bounds, 46, 30, 46, 30); }, 60);
    }).catch(function () {
      el.innerHTML = '<div class="oil-st-map-msg">지도를 불러오지 못했습니다</div>';
    });
  }

  /* ── 시작 ────────────────────────────────────────────────── */
  if (!la || !ln) { location.replace(OIL.cfg.listPageUrl || '/'); return; }
  if (!isMe && qname && PL) PL.remember({ n: qname, a: '', la: la, ln: ln });

  OIL.loading('주변 주유소를 찾는 중...');
  Promise.all([OIL.meta(), OIL.regions()])
    .then(function (a) {
      return collect(a[1]).then(function (data) { render(a[0], data); });
    })
    .catch(OIL.fail);
})();

/* 주유소찾기 - 홈 화면과 동네 상세 화면

   첫 방문:  설정이 펼쳐진 상태 + "내 위치로 찾기" 가 눈에 띄게
   재방문:   저장해둔 우리 동네가 맨 위에, 설정은 한 줄로 접힘
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL) return;
  var mode = window.OIL_MODE;
  if (mode !== 'browse' && mode !== 'area') return;

  var esc = OIL.esc, won = OIL.won;
  var P = OIL.prefs;

  function fuel() { return P ? P.get('fuel') : 'g'; }
  function fuelName() { return P ? P.fuelName() : '휘발유'; }
  /* 동네 요약에서 지금 고른 유종의 통계를 꺼낸다 (없으면 휘발유로) */
  function st(r) { return (r && (r[fuel()] || r.g)) || null; }
  function price(s) { return fuel() === 'd' ? s.d : s.g; }

  function rows(list) {
    return '<div class="oil-rows">' + list.map(function (r) {
      return '<div class="oil-row"><span class="oil-row-k">' + esc(r[0]) + '</span>' +
        '<span class="oil-row-v' + (r[2] ? ' is-accent' : '') + '">' + r[1] + '</span></div>';
    }).join('') + '</div>';
  }

  function stationRow(s) {
    var p = price(s);
    if (!p) return '';
    var badge = '';
    if (s.c === '늘 최저권') badge = '<span class="oil-badge is-low">1년 내내 최저권</span>';
    else if (s.c === '늘 최고권') badge = '<span class="oil-badge is-high">오늘만 쌈</span>';
    return '<div class="oil-list-item"><span class="oil-list-name">' + esc(s.n) +
      (s.s ? '<span class="oil-tag">셀프</span>' : '') + badge + '</span>' +
      '<span class="oil-list-price">' + won(p) + '원</span></div>';
  }

  /* ── 홈 ──────────────────────────────────────────────────── */
  function renderHome(meta, reg) {
    var items = reg.items;
    var mine = null;
    if (P) {
      var slugPref = P.get('home') || P.get('last');
      if (slugPref) {
        for (var i = 0; i < items.length; i++) {
          if (items[i].sl === slugPref) { mine = items[i]; break; }
        }
      }
    }

    var bySido = {};
    items.forEach(function (r) { (bySido[r.sd] = bySido[r.sd] || []).push(r); });
    var sidos = Object.keys(bySido).sort();

    var withFuel = items.filter(st);
    var topSpread = withFuel.slice().sort(function (a, b) { return st(b).sp - st(a).sp; }).slice(0, 8);
    var cheapest = withFuel.slice().sort(function (a, b) { return st(a).md - st(b).md; }).slice(0, 8);

    var natl = fuel() === 'd' ? meta.diesel : meta.gas;

    var html = '<div class="oil-stack">';

    /* 머리말 - 재방문이면 짧게 */
    if (mine) {
      html += '<a class="oil-mine" href="' + OIL.areaUrl(mine.sl) + '">' +
        '<span><span class="oil-mine-k">우리 동네</span>' +
        '<span class="oil-mine-r">' + esc(mine.r) + '</span>' +
        '<span class="oil-mine-s">' + fuelName() + ' 최저 ' + won(st(mine).lo) + '원 · ' +
        '주유소 ' + st(mine).n + '곳</span></span>' + OIL.chev(OIL.cfg.accent || '#A54A04') + '</a>';
    } else {
      html += '<div><div class="oil-kicker">전국 주유소 ' + won(natl.n) + '곳 실제 판매가</div>' +
        '<h1 class="oil-h1">우리 동네 기름값,<br>고를 가치가 있을까요</h1>' +
        '<p class="oil-lead">같은 동네 안에서도 <b>수백 원</b> 차이가 나는 곳이 있고, ' +
        '30원도 차이 안 나는 곳이 있습니다. 어느 쪽인지부터 확인해보세요.</p></div>';
    }

    /* 내 설정 */
    if (P) html += P.barHtml({ regionName: mine ? mine.r : '' });

    /* 오늘 전국 */
    html += '<div class="oil-card">' +
      '<div class="oil-kicker" style="color:var(--oil-muted)">오늘 전국 ' + fuelName() + '</div>' +
      '<div style="display:flex;align-items:baseline;margin-top:5px;">' +
      '<span class="oil-hero">' + won(natl.median) + '원</span>' +
      '<span class="oil-hero-unit">중앙값 · ' + esc(meta.phase) + '</span></div>' +
      rows([
        ['가장 싼 곳 ~ 비싼 곳', won(natl.low) + ' ~ ' + won(natl.high) + '원'],
        ['셀프 / 일반', won(meta['self']) + ' / ' + won(meta.full) + '원'],
        ['동네 안 최대 격차', esc(topSpread[0].r) + ' ' + won(st(topSpread[0]).sp) + '원', true]
      ]) + '</div>';

    /* 동네 찾기 */
    html += '<div class="oil-card"><div class="oil-card-title">우리 동네 찾기</div>';
    if (P) html += P.locateBtnHtml() + '<div style="height:12px;"></div>';
    html += '<input class="oil-search" id="oil-q" type="search" ' +
      'placeholder="또는 동네 이름 입력 (예: 천안)" autocomplete="off" aria-label="동네 검색">' +
      '<div class="oil-suggest" id="oil-sg"></div>' +
      '<div id="oil-browse" style="margin-top:13px;">' +
      '<div class="oil-sido-tabs" id="oil-sidos">' +
      sidos.map(function (s, i) {
        return '<button type="button" class="oil-chip' + (i === 0 ? ' active' : '') +
          '" data-sido="' + esc(s) + '">' + esc(s) + '</button>';
      }).join('') +
      '</div><div class="oil-region-grid" id="oil-regions"></div></div></div>';

    html += OIL.adHtml();

    html += '<div class="oil-card is-flush"><div style="padding:0 16px 8px;">' +
      '<div class="oil-card-title" style="margin:0;">주유소를 고를 가치가 큰 동네</div>' +
      '<p class="oil-p" style="font-size:12.5px;margin:5px 0 0;">동네 안 최저~최고 차이가 가장 큰 곳입니다.</p></div>' +
      '<div class="oil-rank">' + topSpread.map(function (r) {
        return '<a href="' + OIL.areaUrl(r.sl) + '"><span>' + esc(r.r) + '</span>' +
          '<span class="v">' + won(st(r).sp) + '원 차이</span></a>';
      }).join('') + '</div></div>';

    html += '<div class="oil-card is-flush"><div style="padding:0 16px 8px;">' +
      '<div class="oil-card-title" style="margin:0;">오늘 ' + fuelName() +
      OIL.josa(fuelName(), '이가') + ' 싼 동네</div></div>' +
      '<div class="oil-rank">' + cheapest.map(function (r) {
        return '<a href="' + OIL.areaUrl(r.sl) + '"><span>' + esc(r.r) + '</span>' +
          '<span class="v">' + won(st(r).md) + '원</span></a>';
      }).join('') + '</div></div>';

    html += '<a class="oil-btn" href="' + (OIL.cfg.calcPageUrl || '/p/calc.html') + '">' +
      '<span>연간 주유비·경차 환급 계산기</span>' + OIL.chev('#fff') + '</a>';

    html += '<p class="oil-p" style="font-size:11.5px;color:var(--oil-muted);">' +
      OIL.dateKo(meta.date) + ' 실제 판매가 · 출처 오피넷 · 매일 갱신</p></div>';

    OIL.render(html);
    if (P) {
      P.wireBar(function () { renderHome(meta, reg); });
      P.wireLocate();
    }
    wireFind(items, bySido, sidos);
  }

  function wireFind(items, bySido, sidos) {
    var grid = document.getElementById('oil-regions');
    var sidoBox = document.getElementById('oil-sidos');
    var q = document.getElementById('oil-q');
    var sg = document.getElementById('oil-sg');
    var browse = document.getElementById('oil-browse');
    if (!grid) return;

    function showSido(sd) {
      grid.innerHTML = (bySido[sd] || []).slice().sort(function (a, b) {
        return a.r.localeCompare(b.r, 'ko');
      }).map(function (r) {
        var name = r.r.indexOf(' ') > 0 ? r.r.slice(r.r.indexOf(' ') + 1) : r.r;
        return '<a href="' + OIL.areaUrl(r.sl) + '">' + esc(name) + '</a>';
      }).join('');
    }
    showSido(sidos[0]);

    sidoBox.addEventListener('click', function (e) {
      var b = e.target.closest('.oil-chip');
      if (!b) return;
      sidoBox.querySelectorAll('.oil-chip').forEach(function (x) { x.classList.remove('active'); });
      b.classList.add('active');
      showSido(b.getAttribute('data-sido'));
    });

    q.addEventListener('input', function () {
      var v = q.value.trim();
      if (!v) { sg.innerHTML = ''; browse.style.display = ''; return; }
      browse.style.display = 'none';
      var hit = items.filter(function (r) { return r.r.indexOf(v) >= 0 && st(r); }).slice(0, 8);
      sg.innerHTML = hit.length
        ? hit.map(function (r) {
            return '<a href="' + OIL.areaUrl(r.sl) + '">' + esc(r.r) +
              '<span class="s">주유소 ' + st(r).n + '곳 · 최저 ' + won(st(r).lo) + '원</span></a>';
          }).join('')
        : '<div style="padding:10px 12px;font-size:13px;color:#5B666A;">찾는 동네가 없습니다</div>';
    });
  }

  /* ── 동네 상세 ───────────────────────────────────────────── */
  function renderArea(meta, r, total) {
    var s = st(r);
    if (!s) {
      OIL.render('<div class="oil-error">' + esc(r.r) + '은(는) ' + fuelName() +
        ' 자료가 없습니다.<br><a href="' + (OIL.cfg.listPageUrl || '/') + '">다른 동네 보기</a></div>');
      return;
    }
    if (P) P.set('last', r.sl);

    var v = OIL.verdict(r, meta, total, s, fuelName());
    var isHome = P && P.get('home') === r.sl;
    var isWork = P && P.get('work') === r.sl;

    var html = '<div class="oil-stack">';
    var spot = P ? P.get('spot') : '';
    html += '<div><div class="oil-kicker">우리 동네 ' + fuelName() + '</div>' +
      '<h1 class="oil-h1">' + esc(v.head) + '</h1>' +
      (spot ? '<div class="oil-spot">현위치 ' + esc(spot) + '</div>' : '') + '</div>';

    if (P) html += P.barHtml({ regionName: r.r });

    html += '<div class="oil-card"><p class="oil-p">' + v.body + '</p>' +
      '<p class="oil-p" style="font-size:13px;">' + v.nat + '</p>' +
      rows([
        ['주유소', s.n + '곳 (셀프 ' + r.sf + '곳)'],
        ['최저 ~ 최고', won(s.lo) + ' ~ ' + won(s.hi) + '원'],
        ['동네 중앙값', won(s.md) + '원', true]
      ]) + '</div>';

    html += '<div class="oil-save-row">' +
      '<button type="button" class="oil-save' + (isHome ? ' is-on' : '') + '" data-save="home">' +
      (isHome ? '집으로 저장됨' : '집으로 저장') + '</button>' +
      '<button type="button" class="oil-save' + (isWork ? ' is-on' : '') + '" data-save="work">' +
      (isWork ? '회사로 저장됨' : '회사로 저장') + '</button></div>';

    html += OIL.adHtml();

    var list = (r.stations || []).filter(function (x) { return price(x); })
      .sort(function (a, b) { return price(a) - price(b); }).slice(0, 15);
    html += '<div class="oil-card is-flush"><div style="padding:0 16px 10px;">' +
      '<div class="oil-card-title" style="margin:0;">오늘 싼 순서</div>' +
      '<p class="oil-p" style="font-size:12.5px;margin:6px 0 0;">' + OIL.characterLine(r) + '</p></div>' +
      list.map(stationRow).join('') + '</div>';

    html += '<a class="oil-btn" href="' + (OIL.cfg.listPageUrl || '/') + '">' +
      '<span>다른 동네 보기</span>' + OIL.chev('#fff') + '</a>';
    html += '<a class="oil-btn is-ghost" href="' + (OIL.cfg.calcPageUrl || '/p/calc.html') + '">' +
      '<span>내 연간 주유비 계산해보기</span>' + OIL.chev() + '</a>';

    html += '<p class="oil-p" style="font-size:11.5px;color:var(--oil-muted);">' +
      esc(r.r) + ' · ' + OIL.dateKo(meta.date) + ' ' + fuelName() + ' 실제 판매가 ' + s.n +
      '곳 기준 · 1년 성격은 최근 1년 일별 가격으로 산출 · 출처 오피넷</p></div>';

    OIL.render(html);
    document.title = r.r + ' 주유소 최저가 - 오늘 ' + fuelName() + ' ' + won(s.lo) + '원부터';

    if (P) {
      P.wireBar(function () { renderArea(meta, r, total); });
      var root = OIL.root();
      root.addEventListener('click', function (e) {
        var b = e.target.closest('[data-save]');
        if (!b) return;
        var key = b.getAttribute('data-save');
        P.set(key, P.get(key) === r.sl ? '' : r.sl);
        renderArea(meta, r, total);
      });
    }
  }

  /* ── 시작 ────────────────────────────────────────────────── */
  OIL.loading();
  if (mode === 'browse') {
    Promise.all([OIL.meta(), OIL.regions()])
      .then(function (a) { renderHome(a[0], a[1]); }).catch(OIL.fail);
  } else {
    var slug = OIL.param('r');
    if (!slug) { location.replace(OIL.cfg.listPageUrl || '/'); return; }
    Promise.all([OIL.meta(), OIL.region(slug), OIL.regions()])
      .then(function (a) { renderArea(a[0], a[1], a[2].total); }).catch(OIL.fail);
  }
})();

/* 주유소찾기 - 계산기 세 종 (연간 주유비 / 경차 환급 / 우회 손익분기) */
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL || window.OIL_MODE !== 'calc') return;
  var esc = OIL.esc, won = OIL.won;

  /* 경차 유류세 환급 (조세특례제한법) */
  var REFUND_PER_L = 250, REFUND_CAP = 300000;

  function field(id, label, value, unit, hint) {
    return '<div class="oil-field"><label for="' + id + '">' + esc(label) + '</label>' +
      '<div class="oil-field-in"><input id="' + id + '" type="number" inputmode="decimal" value="' +
      value + '"><span class="oil-field-unit">' + esc(unit) + '</span></div>' +
      (hint ? '<div class="oil-field-hint">' + esc(hint) + '</div>' : '') + '</div>';
  }

  function result(id) {
    return '<div class="oil-card is-accent">' +
      '<div class="oil-kicker" id="' + id + '-k">결과</div>' +
      '<div class="oil-hero" id="' + id + '" style="margin-top:6px;">-</div>' +
      '<p class="oil-p" id="' + id + '-s" style="margin-top:9px;font-size:12.5px;"></p></div>';
  }

  function render(meta) {
    var gas = Math.round(meta.gas.median);
    var diesel = Math.round(meta.diesel.median);
    var selfM = Math.round(meta['self']), fullM = Math.round(meta.full);
    var cheap = Math.round(meta.regionCheap.md), pricey = Math.round(meta.regionPricey.md);

    var P = OIL.prefs;
    var car = P ? P.car() : { kmpl: 12, usual: 30, label: '일반 승용차' };
    var isDiesel = P && P.get('fuel') === 'd';
    var baseP = isDiesel ? diesel : gas;

    var html = '<div class="oil-stack">';
    html += '<div><div class="oil-kicker">계산기</div>' +
      '<h1 class="oil-h1">기름값 계산기</h1>' +
      '<p class="oil-lead">전국 ' + won(meta.gas.n) + '곳 실제 판매가로 계산합니다. ' +
      '차종을 고르면 연비와 주유량이 자동으로 채워집니다.</p></div>';
    if (P) html += P.barHtml({});

    /* 탭 */
    html += '<div class="oil-sido-tabs" id="oil-calc-tabs">' +
      ['연간 주유비', '경차 환급', '우회 손익분기'].map(function (t, i) {
        return '<button type="button" class="oil-chip' + (i === 0 ? ' active' : '') +
          '" data-t="' + i + '">' + t + '</button>';
      }).join('') + '</div>';

    /* 1. 연간 주유비 */
    html += '<div class="oil-pane" data-p="0"><div class="oil-card">' +
      field('c1km', '한 달 주행거리', 1200, 'km', '출퇴근 왕복 20km × 22일이면 약 440km입니다') +
      field('c1kmpl', '연비', car.kmpl, 'km/L', car.label + ' 기본값입니다. 내 차 연비를 알면 고쳐주세요') +
      '</div>' + result('c1out') +
      '<div class="oil-card" style="margin-top:12px;">' +
      '<div class="oil-card-title">어디서 넣느냐로 갈리는 돈</div>' +
      '<p class="oil-p" style="font-size:12.5px;">같은 거리를 달려도 주유소를 어떻게 고르느냐에 따라 1년 치가 이만큼 달라집니다.</p>' +
      '<div class="oil-rows"><div class="oil-row">' +
      '<span class="oil-row-k">셀프로만 넣으면 (' + won(fullM - selfM) + '원 저렴)</span>' +
      '<span class="oil-row-v is-accent" id="c1self">-</span></div>' +
      '<div class="oil-row"><span class="oil-row-k">가장 싼 동네 vs 비싼 동네</span>' +
      '<span class="oil-row-v is-accent" id="c1region">-</span></div></div>' +
      '<p class="oil-p" style="font-size:12px;color:#6B7679;margin-top:11px;">오늘 ' +
      esc(meta.regionCheap.r) + ' ' + won(cheap) + '원이 가장 낮고 ' +
      esc(meta.regionPricey.r) + ' ' + won(pricey) + '원이 가장 높습니다.</p></div></div>';

    /* 2. 경차 환급 */
    html += '<div class="oil-pane" data-p="1" hidden><div class="oil-card">' +
      field('c2m', '한 달 주유량', 40, 'L', '월 주유비를 오늘 중앙값으로 나누면 대략 나옵니다') +
      '</div>' + result('c2out') +
      '<div class="oil-card" style="margin-top:12px;">' +
      '<div class="oil-card-title">알아두실 것</div>' +
      '<div class="oil-rows" style="margin-top:0;">' +
      '<div class="oil-row"><span class="oil-row-k">환급 단가</span><span class="oil-row-v">리터당 ' + REFUND_PER_L + '원</span></div>' +
      '<div class="oil-row"><span class="oil-row-k">연 한도</span><span class="oil-row-v">' + won(REFUND_CAP) + '원</span></div>' +
      '<div class="oil-row"><span class="oil-row-k">한도까지 주유량</span><span class="oil-row-v is-accent">' +
      won(REFUND_CAP / REFUND_PER_L) + 'L</span></div></div>' +
      '<p class="oil-p" style="margin-top:12px;">전용 유류구매카드로 결제해야 자동 적용됩니다. ' +
      '일반 카드로 결제하면 소급되지 않습니다. 한도는 매년 1월에 초기화됩니다.</p>' +
      '<div class="oil-note" style="margin-top:11px;">환급 단가와 한도는 법 개정에 따라 바뀔 수 있습니다. ' +
      '현재 적용 기준은 국세청 또는 카드사에 확인하세요.</div></div></div>';

    /* 3. 우회 손익분기 */
    html += '<div class="oil-pane" data-p="2" hidden><div class="oil-card">' +
      field('c3gap', '리터당 가격 차이', 50, '원', '거기가 여기보다 얼마나 싼가요') +
      field('c3l', '넣을 양', car.usual, 'L', car.label + ' 1회 주유량 기준') +
      field('c3kmpl', '연비', car.kmpl, 'km/L', car.label + ' 기본값') +
      field('c3p', '기름값', baseP, '원/L', '오늘 전국 ' + (isDiesel ? '경유' : '휘발유') + ' 중앙값') +
      '</div>' + result('c3out') +
      '<div class="oil-card" style="margin-top:12px;">' +
      '<div class="oil-card-title">계산 근거</div>' +
      '<div class="oil-rows" style="margin-top:0;">' +
      '<div class="oil-row"><span class="oil-row-k">싸게 넣어서 아끼는 돈</span><span class="oil-row-v" id="c3save">-</span></div>' +
      '<div class="oil-row"><span class="oil-row-k">1km 더 달리는 비용</span><span class="oil-row-v is-accent" id="c3cost">-</span></div></div>' +
      '<p class="oil-p" style="margin-top:12px;">여기서 말하는 거리는 <b>왕복이 아니라 우회분</b>입니다. ' +
      '가던 길에서 벗어났다가 다시 돌아오는 데 추가로 드는 거리만 셉니다.</p></div></div>';

    html += OIL.adHtml();
    html += '<a class="oil-btn" href="' + (OIL.cfg.listPageUrl || '/') + '">' +
      '<span>우리 동네 기름값 보기</span>' + OIL.chev('#fff') + '</a>';
    html += '<p class="oil-p" style="font-size:11.5px;color:var(--oil-muted);">' +
      OIL.dateKo(meta.date) + ' 실제 판매가 기준 · 출처 오피넷 · 실제 주유비는 운전 습관·유가 변동에 따라 달라집니다</p>';
    html += '</div>';

    OIL.render(html);
    /* 블로그스팟이 "주유소찾기: calc" 로 붙이는 제목을 검색용으로 바꾼다 */
    document.title = '기름값 계산기 - 연간 주유비·경차 환급·우회 손익분기';
    wire(gas, diesel, selfM, fullM, cheap, pricey, isDiesel);
    if (P) P.wireBar(function () { render(meta); });
  }

  function wire(gas, diesel, selfM, fullM, cheap, pricey, isDiesel) {
    var $ = function (id) { return document.getElementById(id); };

    var tabs = $('oil-calc-tabs');
    tabs.addEventListener('click', function (e) {
      var b = e.target.closest('.oil-chip');
      if (!b) return;
      tabs.querySelectorAll('.oil-chip').forEach(function (x) { x.classList.remove('active'); });
      b.classList.add('active');
      var t = b.getAttribute('data-t');
      document.querySelectorAll('.oil-pane').forEach(function (p) {
        p.hidden = p.getAttribute('data-p') !== t;
      });
    });

    function c1() {
      var km = parseFloat($('c1km').value) || 0;
      var kmpl = parseFloat($('c1kmpl').value) || 0;
      var isG = !isDiesel;
      $('c1out-k').textContent = '연간 주유비';
      if (kmpl <= 0) { $('c1out').textContent = '-'; $('c1out-s').textContent = '연비를 입력해주세요.'; return; }
      var base = isG ? gas : diesel;
      var liters = (km * 12) / kmpl;
      $('c1out').textContent = won(liters * base) + '원';
      $('c1out-s').innerHTML = '1년에 약 <b>' + won(liters) + 'L</b>를 넣게 됩니다 (월 ' +
        won(km / kmpl) + 'L). 오늘 전국 중앙값 ' + won(base) + '원 기준입니다.';
      $('c1self').textContent = won(liters * (fullM - selfM)) + '원';
      $('c1region').textContent = won(liters * (pricey - cheap)) + '원';
    }

    function c2() {
      var m = parseFloat($('c2m').value) || 0;
      var yearL = m * 12;
      var refund = Math.min(yearL * REFUND_PER_L, REFUND_CAP);
      $('c2out-k').textContent = '연간 환급액';
      $('c2out').textContent = won(refund) + '원';
      if (yearL <= 0) { $('c2out-s').textContent = '월 주유량을 입력해주세요.'; return; }
      if (yearL * REFUND_PER_L >= REFUND_CAP) {
        $('c2out-s').innerHTML = '연 한도 <b>30만원</b>을 채웁니다. 약 <b>' +
          (REFUND_CAP / REFUND_PER_L / m).toFixed(1) + '개월</b>이면 한도에 도달하고, 그 뒤 주유분은 환급되지 않습니다.';
      } else {
        $('c2out-s').innerHTML = '1년에 <b>' + won(yearL) + 'L</b>를 넣으시는 기준입니다. 한도까지 <b>' +
          won(REFUND_CAP - yearL * REFUND_PER_L) + '원</b>이 남아, 더 넣으셔도 전액 환급 대상입니다.';
      }
    }

    function c3() {
      var gap = parseFloat($('c3gap').value) || 0;
      var l = parseFloat($('c3l').value) || 0;
      var kmpl = parseFloat($('c3kmpl').value) || 0;
      var p = parseFloat($('c3p').value) || 0;
      $('c3out-k').textContent = '여기까지는 돌아가도 본전';
      if (gap <= 0 || kmpl <= 0 || p <= 0) {
        $('c3out').textContent = '-'; $('c3out-s').textContent = '값을 모두 입력해주세요.'; return;
      }
      var perKm = p / kmpl;
      var km = (gap * l) / perKm;
      $('c3out').textContent = km.toFixed(1) + 'km';
      $('c3out-s').innerHTML = '리터당 <b>' + won(gap) + '원</b> 싼 곳에 <b>' + won(l) +
        'L</b>를 넣는다면, <b>' + km.toFixed(1) + 'km</b>까지 돌아가도 본전입니다. ' +
        '이보다 멀면 아낀 돈보다 쓴 기름값이 큽니다.';
      $('c3save').textContent = won(gap * l) + '원';
      $('c3cost').textContent = won(perKm) + '원';
    }

    ['c1km', 'c1kmpl'].forEach(function (id) {
      $(id).addEventListener('input', c1); $(id).addEventListener('change', c1);
    });
    $('c2m').addEventListener('input', c2);
    ['c3gap', 'c3l', 'c3kmpl', 'c3p'].forEach(function (id) { $(id).addEventListener('input', c3); });
    c1(); c2(); c3();
  }

  OIL.loading();
  OIL.meta().then(render).catch(OIL.fail);
})();

/* 주유소찾기 - 블로그 글 보조
   글 본문은 블로그스팟 편집기에 붙여넣는 것이라 <script> 를 쓸 수 없다.
   그래서 본문에는 '표시'만 남기고 실제 일은 여기서 한다.

     <div class="oil-ad-here"></div>      -> 그 자리에 광고를 끼워 넣는다
     <span data-oil="selfGap"></span>     -> 오늘 데이터 값으로 채운다

   덕분에 글을 다시 쓰지 않아도 숫자가 매일 최신이 된다.
*/
(function () {
  'use strict';

  var OIL = window.OIL;
  if (!OIL || window.OIL_MODE !== 'blog') return;

  var won = OIL.won;

  /* 본문에서 쓸 수 있는 값들 */
  var FIELD = {
    date: function (m) { return OIL.dateKo(m.date); },
    phase: function (m) { return m.phase; },
    gasN: function (m) { return won(m.gas.n); },
    gasMedian: function (m) { return won(m.gas.median); },
    gasLow: function (m) { return won(m.gas.low); },
    gasHigh: function (m) { return won(m.gas.high); },
    dieselMedian: function (m) { return won(m.diesel.median); },
    selfMedian: function (m) { return won(m['self']); },
    fullMedian: function (m) { return won(m.full); },
    selfGap: function (m) { return won(m.selfGap); },
    weekdayGap: function (m) { return m.weekdayGap.toFixed(1); },
    spreadMedian: function (m) { return won(m.spreadMedian); },
    topSpreadName: function (m) { return m.topSpread.r; },
    topSpreadValue: function (m) { return won(m.topSpread.sp); },
    cheapName: function (m) { return m.regionCheap.r; },
    cheapValue: function (m) { return won(m.regionCheap.md); },
    priceyName: function (m) { return m.regionPricey.r; },
    priceyValue: function (m) { return won(m.regionPricey.md); }
  };

  function fillNumbers(meta) {
    var nodes = document.querySelectorAll('.post-body [data-oil]');
    for (var i = 0; i < nodes.length; i++) {
      var key = nodes[i].getAttribute('data-oil');
      var fn = FIELD[key];
      if (!fn) continue;
      try { nodes[i].textContent = fn(meta); } catch (e) { /* 값이 없으면 그대로 둔다 */ }
    }
  }

  function fillAds() {
    var spots = document.querySelectorAll('.post-body .oil-ad-here');
    if (!spots.length) return;
    var html = OIL.adHtml();
    if (!html) return;
    for (var i = 0; i < spots.length; i++) {
      if (spots[i].getAttribute('data-done')) continue;
      spots[i].innerHTML = html;
      spots[i].setAttribute('data-done', '1');
    }
    OIL.adFill();
  }

  /* ── 위젯이 없을 때를 위한 대비 ───────────────────────────
     블로그스팟이 테마를 받을 때 '블로그 게시물' 위젯을 빠뜨리는 일이 있다.
     그러면 글이 통째로 안 보이므로, 블로거 피드에서 직접 가져와 그린다.
     위젯이 정상이면 이 코드는 아무 일도 하지 않는다. */
  function feedUrl() {
    var path = location.pathname;
    var m = path.match(/^\/search\/label\/(.+?)\/?$/);
    if (m) {
      return '/feeds/posts/default/-/' + m[1] + '?alt=json&max-results=25';
    }
    if (/\.html$/.test(path)) {
      return '/feeds/posts/default?alt=json&max-results=1&path=' + encodeURIComponent(path);
    }
    return '/feeds/posts/default?alt=json&max-results=25';
  }

  function entryUrl(e) {
    var links = e.link || [];
    for (var i = 0; i < links.length; i++) {
      if (links[i].rel === 'alternate') return links[i].href;
    }
    return '#';
  }

  function renderFeed(entries, single) {
    var wrap = document.querySelector('.oil-blog-wrap');
    if (!wrap) return;
    if (!entries.length) {
      wrap.innerHTML = '<div class="oil-error">글이 없습니다.</div>';
      return;
    }
    wrap.innerHTML = entries.map(function (e) {
      var title = (e.title && e.title.$t) || '';
      var body = (e.content && e.content.$t) || (e.summary && e.summary.$t) || '';
      if (single) {
        return '<div class="post"><h1 class="post-title">' + OIL.esc(title) + '</h1>' +
          '<div class="post-body">' + body + '</div></div>';
      }
      var text = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 95);
      return '<a class="post" href="' + entryUrl(e) + '" style="display:block;">' +
        '<div class="post-title" style="margin-bottom:8px;">' + OIL.esc(title) + '</div>' +
        '<div style="font-size:13px;line-height:1.7;color:#5B666A;">' + OIL.esc(text) + '...</div></a>';
    }).join('');
  }

  function loadFromFeed() {
    var single = /\.html$/.test(location.pathname) &&
                 !/^\/search\//.test(location.pathname);
    fetch(feedUrl(), { cache: 'no-cache' })
      .then(function (r) { return r.json(); })
      .then(function (js) {
        renderFeed((js.feed && js.feed.entry) || [], single);
        fillAds();
        return OIL.meta().then(fillNumbers);
      })
      .catch(function (e) { if (window.console) console.error(e); });
  }

  function run() {
    /* 위젯이 글을 그렸는지 확인 */
    if (!document.querySelector('.post-body')) {
      loadFromFeed();
      return;
    }
    fillAds();
    if (!document.querySelector('.post-body [data-oil]')) return;
    OIL.meta().then(fillNumbers).catch(function () { /* 숫자는 못 채워도 글은 읽힌다 */ });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else {
    run();
  }
})();

//
